export const BODY = {"level-5":{"id":"level-5","kind":"level","level":5,"src":"level:5","title":"Level 5 · Point and Per Cent","body":"Long multiplication, which sum comes first, primes, squares and cubes, decimals and percentages, sales and profit, area and angles on a line, and the mean.","route":"#/atlas","cta":"See the road"},"land-l5-muldiv":{"id":"land-l5-muldiv","kind":"land","level":5,"src":"land:l5-muldiv","title":"Long sums, in order — in The Number Library","body":"3 stops on this stretch of the road: Long multiplication · Which sum first? · Problems in steps.","art":"art/w-library.webp","route":"#/world/library","cta":"Visit Library"},"land-l5-powers":{"id":"land-l5-powers","kind":"land","level":5,"src":"land:l5-powers","title":"Tests, primes and powers — in The Square Palace","body":"5 stops on this stretch of the road: Tests for 4 and 8 · Is it prime? · Squaring numbers that end in 5 · What a square number is · Powers: the little number.","art":"art/w-palace.webp","route":"#/world/palace","cta":"Visit Palace"},"land-l5-decimals":{"id":"land-l5-decimals","kind":"land","level":5,"src":"land:l5-decimals","title":"Fractions, decimals, per cents — in The Decimal Dock","body":"6 stops on this stretch of the road: Same share, different pieces · Which slice is bigger? · Line up the point · Rounding decimals · Fractions, decimals, per cents · Percentages of an amount.","art":"art/w-dock.webp","route":"#/world/dock","cta":"Visit Dock"},"land-l5-money":{"id":"land-l5-money","kind":"land","level":5,"src":"land:l5-money","title":"Sales and profit — in Coin Street","body":"3 stops on this stretch of the road: The best buy · A sale · Profit and loss.","art":"art/w-coinstreet.webp","route":"#/world/coinstreet","cta":"Visit Coins"},"land-l5-measure":{"id":"land-l5-measure","kind":"land","level":5,"src":"land:l5-measure","title":"Area and angles — in The Clock Tower","body":"4 stops on this stretch of the road: Perimeter · Area of a rectangle · Area of an L-shape · Angles on a line and round a point.","art":"art/w-clocktower.webp","route":"#/world/clocktower","cta":"Visit Clock Tower"},"land-l5-data":{"id":"land-l5-data","kind":"land","level":5,"src":"land:l5-data","title":"Averages and working back — in The Data Carnival","body":"3 stops on this stretch of the road: The mean: fair shares · The range: how spread out? · Working backwards.","art":"art/w-carnival.webp","route":"#/world/carnival","cta":"Visit Carnival"},"trick-long-multiply-idea":{"id":"trick-long-multiply-idea","kind":"trick","src":"stop:long-multiply#idea","title":"Long multiplication","body":"Split both numbers by place, multiply every part by every part in a grid, and add the boxes. 46 × 37 means 46 rows of 37. Split the 46 into 40 and 6, and the 37 into 30 and 7, and the rectangle cuts into four smaller rectangles: 40 × 30, 40 × 7, 6 × 30 and 6 × 7. Every one is a times-table fact with some zeros.","cta":"Learn the trick","level":5,"route":"#/stop/long-multiply"},"story-long-multiply-open":{"id":"story-long-multiply-open","kind":"story","src":"story:long-multiply#open","badge":{"id":"story","label":"A story"},"title":"Tiling the reading room","body":"The reading-room floor is 46 tiles long and 37 tiles wide. How many tiles? — with Mira and Rafi.","art":"art/s-library.webp","cta":"Read the story","level":5,"route":"#/stop/long-multiply"},"hook-long-multiply-hook":{"id":"hook-long-multiply-hook","kind":"hook","src":"stop:long-multiply#hook","title":"Can you? — Long multiplication","body":"46 × 37 — both numbers too big for the tables.","cta":"Find out how","level":5,"route":"#/stop/long-multiply"},"idea-long-multiply-case0":{"id":"idea-long-multiply-case0","kind":"idea","src":"stop:long-multiply#case0","title":"Long multiplication: Two-digit: the grid","body":"Two parts each way make four boxes. Every box is a times-table fact with zeros, and the four add up to the whole.","cta":"See it worked","level":5,"route":"#/stop/long-multiply"},"worked-long-multiply-worked0":{"id":"worked-long-multiply-worked0","kind":"worked","src":"stop:long-multiply#worked0","title":"Worked out — Long multiplication: Two-digit: the grid","body":"46 × 37: 40 × 30 → 1200 · 40 × 7 → 280 · 6 × 30 → 180 · 6 × 7 → 42 · Add all four boxes → 1702","cta":"Watch it step by step","level":5,"route":"#/stop/long-multiply"},"idea-long-multiply-case1":{"id":"idea-long-multiply-case1","kind":"idea","src":"stop:long-multiply#case1","title":"Long multiplication: Three-digit: two rows","body":"With a three-digit number, work in rows: the whole top number times the ones, then times the tens (write a 0 first). Add the two rows.","cta":"See it worked","level":5,"route":"#/stop/long-multiply"},"worked-long-multiply-worked1":{"id":"worked-long-multiply-worked1","kind":"worked","src":"stop:long-multiply#worked1","title":"Worked out — Long multiplication: Three-digit: two rows","body":"234 × 26: First row: 234 × 6 → 1404 · Second row: 234 × 20 (write a 0, then × 2) → 4680 · Add the two rows → 6084","cta":"Watch it step by step","level":5,"route":"#/stop/long-multiply"},"why-long-multiply-why1":{"id":"why-long-multiply-why1","kind":"why","src":"stop:long-multiply#why1","title":"Why “Long multiplication” works","body":"The four boxes cover the whole rectangle exactly once — no gaps, no overlaps — so their areas add up to the whole: 1200 + 280 + 180 + 42 = 1702.","cta":"See why","level":5,"route":"#/stop/long-multiply"},"why-long-multiply-why2":{"id":"why-long-multiply-why2","kind":"why","src":"stop:long-multiply#why2","title":"Why “Long multiplication” works","body":"The column method is the same grid folded up — and it is the quicker way once a number has three digits. The first row is the whole top number times the ones (46 × 7); the second row is it times the tens (46 × 30, which is why you write a 0 first). Add the two rows and you have added all the boxes.","cta":"See why","level":5,"route":"#/stop/long-multiply"},"algebra-long-multiply-alg":{"id":"algebra-long-multiply-alg","kind":"algebra","src":"stop:long-multiply#alg","title":"The algebra behind “Long multiplication”","body":"(10a + b)(10c + d) = 100ac + 10ad + 10bc + bd","cta":"See why","level":5,"route":"#/stop/long-multiply"},"moment-long-multiply-beat3":{"id":"moment-long-multiply-beat3","kind":"moment","src":"story:long-multiply#beat3","badge":{"id":"story","label":"A story"},"title":"Tiling the reading room — on the notepad","body":"Mira: Two long strips. 40 × 7 + 6 × 30 = 460","cta":"Read the story","level":5,"route":"#/stop/long-multiply"},"moral-long-multiply-beat5":{"id":"moral-long-multiply-beat5","kind":"moral","src":"story:long-multiply#beat5","badge":{"id":"story","label":"A story"},"title":"Mira, in “Tiling the reading room”","body":"Add all four pieces together: the whole floor.","cta":"Read the story","level":5,"route":"#/stop/long-multiply"},"try-long-multiply-L5":{"id":"try-long-multiply-L5","kind":"try","level":5,"src":"try:long-multiply@5/1#0","title":"Long multiplication — your turn","route":"#/stop/long-multiply","cta":"Practise this stop","play":{"q":"17 × 12 = ?","opts":["204","100","20"],"after":"Split both numbers by place, multiply every part by every part in a grid, and add the boxes."}},"trick-order-of-operations-idea":{"id":"trick-order-of-operations-idea","kind":"trick","src":"stop:order-of-operations#idea","title":"Which sum first?","body":"Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right. A calculation written in a line could be read more than one way. 2 + 3 × 4 is 20 if you add first and 14 if you multiply first. Maths only works if everyone gets the same answer, so everyone agrees an order. You may know it as BODMAS or BIDMAS in Britain and India, or PEMDAS in America — they are the same rule.","cta":"Learn the trick","level":5,"route":"#/stop/order-of-operations"},"story-order-of-operations-open":{"id":"story-order-of-operations-open","kind":"story","src":"story:order-of-operations#open","badge":{"id":"story","label":"A story"},"title":"The library quiz","body":"The quiz card at the library desk says: 2 + 3 × 4. — with Kwame and Pip.","art":"art/s-library.webp","cta":"Read the story","level":5,"route":"#/stop/order-of-operations"},"hook-order-of-operations-hook":{"id":"hook-order-of-operations-hook","kind":"hook","src":"stop:order-of-operations#hook","title":"Can you? — Which sum first?","body":"2 + 3 × 4 — is it 20 or 14?","cta":"Find out how","level":5,"route":"#/stop/order-of-operations"},"idea-order-of-operations-case0":{"id":"idea-order-of-operations-case0","kind":"idea","src":"stop:order-of-operations#case0","title":"Which sum first?: × and ÷ before + and −","body":"A multiplication is one bundle — three fours is 12 — so work it out before you add anything to it.","cta":"See it worked","level":5,"route":"#/stop/order-of-operations"},"worked-order-of-operations-worked0":{"id":"worked-order-of-operations-worked0","kind":"worked","src":"stop:order-of-operations#worked0","title":"Worked out — Which sum first?: × and ÷ before + and −","body":"2 + 3 × 4: Multiply first: 3 × 4 → 12 · 2 + 12 → 14","cta":"Watch it step by step","level":5,"route":"#/stop/order-of-operations"},"idea-order-of-operations-case1":{"id":"idea-order-of-operations-case1","kind":"idea","src":"stop:order-of-operations#case1","title":"Which sum first?: Brackets first","body":"Brackets change the order on purpose: whatever is inside them is done first, even an adding sum.","cta":"See it worked","level":5,"route":"#/stop/order-of-operations"},"worked-order-of-operations-worked1":{"id":"worked-order-of-operations-worked1","kind":"worked","src":"stop:order-of-operations#worked1","title":"Worked out — Which sum first?: Brackets first","body":"(2 + 3) × 4: Brackets first: 2 + 3 → 5 · 5 × 4 → 20","cta":"Watch it step by step","level":5,"route":"#/stop/order-of-operations"},"idea-order-of-operations-case2":{"id":"idea-order-of-operations-case2","kind":"idea","src":"stop:order-of-operations#case2","title":"Which sum first?: Powers before ×","body":"A power like 3² is a bundle too — 3 × 3 — and it comes before multiplying or adding.","cta":"See it worked","level":5,"route":"#/stop/order-of-operations"},"worked-order-of-operations-worked2":{"id":"worked-order-of-operations-worked2","kind":"worked","src":"stop:order-of-operations#worked2","title":"Worked out — Which sum first?: Powers before ×","body":"5 + 3² × 2: Powers first: 3² → 9 · 9 × 2 → 18 · 5 + 18 → 23","cta":"Watch it step by step","level":5,"route":"#/stop/order-of-operations"},"idea-order-of-operations-case3":{"id":"idea-order-of-operations-case3","kind":"idea","src":"stop:order-of-operations#case3","title":"Which sum first?: Same rank: left to right","body":"Do the × and ÷ bundles first. Then the + and − are the same rank, so go strictly left to right.","cta":"See it worked","level":5,"route":"#/stop/order-of-operations"},"worked-order-of-operations-worked3":{"id":"worked-order-of-operations-worked3","kind":"worked","src":"stop:order-of-operations#worked3","title":"Worked out — Which sum first?: Same rank: left to right","body":"30 − 12 ÷ 4 + 2 × 5: 12 ÷ 4 → 3 · 2 × 5 → 10 · Now left to right: 30 − 3 → 27 · 27 + 10 → 37","cta":"Watch it step by step","level":5,"route":"#/stop/order-of-operations"},"why-order-of-operations-why1":{"id":"why-order-of-operations-why1","kind":"why","src":"stop:order-of-operations#why1","title":"Why “Which sum first?” works","body":"Multiplying goes before adding because a multiplication is a bundle: 3 × 4 is \"three fours\", a single amount, 12. The 2 is added to that amount. If you want the 2 and 3 to go together first, you have to say so with brackets: (2 + 3) × 4.","cta":"See why","level":5,"route":"#/stop/order-of-operations"},"why-order-of-operations-why2":{"id":"why-order-of-operations-why2","kind":"why","src":"stop:order-of-operations#why2","title":"Why “Which sum first?” works","body":"× and ÷ are the same rank, and so are + and −, so between those you just go left to right: 20 − 6 + 3 is 14 + 3 = 17, not 20 − 9.","cta":"See why","level":5,"route":"#/stop/order-of-operations"},"why-order-of-operations-why3":{"id":"why-order-of-operations-why3","kind":"why","src":"stop:order-of-operations#why3","title":"Why “Which sum first?” works","body":"Powers come before × and ÷ because a power is a bundle of multiplications: 3² is 3 × 3, a single amount, 9. So 5 + 3² × 2 is 5 + 9 × 2 = 5 + 18 = 23.","cta":"See why","level":5,"route":"#/stop/order-of-operations"},"algebra-order-of-operations-alg":{"id":"algebra-order-of-operations-alg","kind":"algebra","src":"stop:order-of-operations#alg","title":"The algebra behind “Which sum first?”","body":"Brackets → Orders (powers) → × ÷ (left to right) → + − (left to right)","cta":"See why","level":5,"route":"#/stop/order-of-operations"},"moment-order-of-operations-beat3":{"id":"moment-order-of-operations-beat3","kind":"moment","src":"story:order-of-operations#beat3","badge":{"id":"story","label":"A story"},"title":"The library quiz — on the notepad","body":"Kwame: Then add the 2. 2 + 12 = 14","cta":"Read the story","level":5,"route":"#/stop/order-of-operations"},"moral-order-of-operations-beat6":{"id":"moral-order-of-operations-beat6","kind":"moral","src":"story:order-of-operations#beat6","badge":{"id":"story","label":"A story"},"title":"Pip, in “The library quiz”","body":"Without brackets, the card’s answer is 14.","cta":"Read the story","level":5,"route":"#/stop/order-of-operations"},"try-order-of-operations-L5":{"id":"try-order-of-operations-L5","kind":"try","level":5,"src":"try:order-of-operations@5/1#0","title":"Which sum first? — your turn","route":"#/stop/order-of-operations","cta":"Practise this stop","play":{"q":"38 − 2 × 4 = ?","opts":["30","8","31"],"after":"Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right."}},"hook-perimeter-hook":{"id":"hook-perimeter-hook","kind":"hook","src":"stop:perimeter#hook","title":"Can you? — Perimeter","body":"A garden is 8 m by 5 m. How much fence goes all the way round?","cta":"Find out how","level":5,"route":"#/stop/perimeter"},"worked-perimeter-worked0":{"id":"worked-perimeter-worked0","kind":"worked","src":"stop:perimeter#worked0","title":"Worked out — Perimeter: A rectangle","body":"A rectangle is 8 cm long and 5 cm wide. What is its perimeter, in cm?: One length and one width: 8 + 5 → 13 · Two of each: double it → 26","cta":"Watch it step by step","level":5,"route":"#/stop/perimeter"},"worked-perimeter-worked1":{"id":"worked-perimeter-worked1","kind":"worked","src":"stop:perimeter#worked1","title":"Worked out — Perimeter: A square","body":"A square has sides of 6 cm. What is its perimeter, in cm?: A square has four equal sides → 4 · 4 × 6 → 24","cta":"Watch it step by step","level":5,"route":"#/stop/perimeter"},"why-perimeter-why1":{"id":"why-perimeter-why1","kind":"why","src":"stop:perimeter#why1","title":"Why “Perimeter” works","body":"An L-shape looks harder, but it is not. Push the two sides of the cut-out corner outwards and they line up exactly with the missing corner of a full rectangle. The steps up and across still add up to the full height and the full width.","cta":"See why","level":5,"route":"#/stop/perimeter"},"algebra-perimeter-alg":{"id":"algebra-perimeter-alg","kind":"algebra","src":"stop:perimeter#alg","title":"The algebra behind “Perimeter”","body":"rectangle: P = 2(l + w) · L-shape: P = 2(W + H)","cta":"See why","level":5,"route":"#/stop/perimeter"},"moral-perimeter-beat5":{"id":"moral-perimeter-beat5","kind":"moral","src":"story:perimeter#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “Fencing the vegetable patch”","body":"Twenty-six metres of fence, all the way round.","cta":"Read the story","level":5,"route":"#/stop/perimeter"},"try-perimeter-L5":{"id":"try-perimeter-L5","kind":"try","level":5,"src":"try:perimeter@5/2#0","title":"Perimeter — your turn","route":"#/stop/perimeter","cta":"Practise this stop","play":{"q":"A square has sides of 8 cm. What is its perimeter, in cm?","opts":["32","4","33"],"after":"Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width)."}},"hook-area-rectangles-hook":{"id":"hook-area-rectangles-hook","kind":"hook","src":"stop:area-rectangles#hook","title":"Can you? — Area of a rectangle","body":"A rug is 7 squares long and 6 squares wide. How many squares does it cover — without counting them all?","cta":"Find out how","level":5,"route":"#/stop/area-rectangles"},"idea-area-rectangles-case1":{"id":"idea-area-rectangles-case1","kind":"idea","src":"stop:area-rectangles#case1","title":"Area of a rectangle: Length × width","body":"The length is how many squares fit in a row and the width is how many rows, so the area is the two multiplied.","cta":"See it worked","level":5,"route":"#/stop/area-rectangles"},"idea-area-rectangles-case2":{"id":"idea-area-rectangles-case2","kind":"idea","src":"stop:area-rectangles#case2","title":"Area of a rectangle: Finding a missing side","body":"Now the area is given and a side is missing. Undo the multiplying: divide the area by the side you know.","cta":"See it worked","level":5,"route":"#/stop/area-rectangles"},"why-area-rectangles-why1":{"id":"why-area-rectangles-why1","kind":"why","src":"stop:area-rectangles#why1","title":"Why “Area of a rectangle” works","body":"Lay the squares in a rectangle and they make neat rows. Every row has the same number of squares — the length — and there are as many rows as the width. Equal rows are exactly what multiplying counts: 6 rows of 7 is 6 × 7 = 42.","cta":"See why","level":5,"route":"#/stop/area-rectangles"},"algebra-area-rectangles-alg":{"id":"algebra-area-rectangles-alg","kind":"algebra","src":"stop:area-rectangles#alg","title":"The algebra behind “Area of a rectangle”","body":"A = l × w · w = A ÷ l","cta":"See why","level":5,"route":"#/stop/area-rectangles"},"moral-area-rectangles-beat5":{"id":"moral-area-rectangles-beat5","kind":"moral","src":"story:area-rectangles#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The new rug”","body":"Forty-two squares. Length times width!","cta":"Read the story","level":5,"route":"#/stop/area-rectangles"},"try-area-rectangles-L5":{"id":"try-area-rectangles-L5","kind":"try","level":5,"src":"try:area-rectangles@5/2#0","title":"Area of a rectangle — your turn","route":"#/stop/area-rectangles","cta":"Practise this stop","play":{"q":"A rectangle is 2 cm long and 11 cm wide. What is its area, in cm²?","opts":["22","2","11"],"after":"Area is how many unit squares cover a shape. A rectangle is rows of equal squares, so area = length × width."}},"trick-compound-area-idea":{"id":"trick-compound-area-idea","kind":"trick","src":"stop:compound-area#idea","title":"Area of an L-shape","body":"Cut the L into two rectangles, find each area, and add them. Area does not change when you cut a shape up: the same floor is covered, just in two pieces. So an L-shape can be split with one straight line into two rectangles, and each rectangle is length × width.","cta":"Learn the trick","level":5,"route":"#/stop/compound-area"},"story-compound-area-open":{"id":"story-compound-area-open","kind":"story","src":"story:compound-area#open","badge":{"id":"story","label":"A story"},"title":"Carpet for the L-shaped hall","body":"A hall is shaped like an L: 8 m across the bottom, 7 m up the side, with a corner missing. — with Rafi and Ines.","art":"art/s-hall.webp","cta":"Read the story","level":5,"route":"#/stop/compound-area"},"hook-compound-area-hook":{"id":"hook-compound-area-hook","kind":"hook","src":"stop:compound-area#hook","title":"Can you? — Area of an L-shape","body":"A room is shaped like an L. How much carpet does it need?","cta":"Find out how","level":5,"route":"#/stop/compound-area"},"why-compound-area-why1":{"id":"why-compound-area-why1","kind":"why","src":"stop:compound-area#why1","title":"Why “Area of an L-shape” works","body":"The only work is finding the sides of each piece. The height of the upper piece is the full height take away the bottom strip, because the two heights stack to make the whole side.","cta":"See why","level":5,"route":"#/stop/compound-area"},"why-compound-area-why2":{"id":"why-compound-area-why2","kind":"why","src":"stop:compound-area#why2","title":"Why “Area of an L-shape” works","body":"There is a second road to the same answer: the L is the full rectangle around it with one corner missing. Full rectangle minus the missing corner must give the same number — which is a good way to check.","cta":"See why","level":5,"route":"#/stop/compound-area"},"algebra-compound-area-alg":{"id":"algebra-compound-area-alg","kind":"algebra","src":"stop:compound-area#alg","title":"The algebra behind “Area of an L-shape”","body":"A = W × h₁ + w₁ × (H − h₁) = W × H − (W − w₁)(H − h₁)","cta":"See why","level":5,"route":"#/stop/compound-area"},"moment-compound-area-beat3":{"id":"moment-compound-area-beat3","kind":"moment","src":"story:compound-area#beat3","badge":{"id":"story","label":"A story"},"title":"Carpet for the L-shaped hall — on the notepad","body":"Ines: The part above is 3 m wide and 7 − 3 = 4 m tall. 3 × 4 = 12","cta":"Read the story","level":5,"route":"#/stop/compound-area"},"moral-compound-area-beat5":{"id":"moral-compound-area-beat5","kind":"moral","src":"story:compound-area#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “Carpet for the L-shaped hall”","body":"Both roads agree — 36 square metres of carpet.","cta":"Read the story","level":5,"route":"#/stop/compound-area"},"hook-equivalent-fractions-hook":{"id":"hook-equivalent-fractions-hook","kind":"hook","src":"stop:equivalent-fractions#hook","title":"Can you? — Same share, different pieces","body":"3/4 = ?/12 — how many twelfths is three quarters?","cta":"Find out how","level":5,"route":"#/stop/equivalent-fractions"},"worked-equivalent-fractions-worked0":{"id":"worked-equivalent-fractions-worked0","kind":"worked","src":"stop:equivalent-fractions#worked0","title":"Worked out — Same share, different pieces: Missing top","body":"3/4 = ?/12: 4 × what makes 12? → 3 · Same to the top: 3 × 3 → 9","cta":"Watch it step by step","level":5,"route":"#/stop/equivalent-fractions"},"worked-equivalent-fractions-worked1":{"id":"worked-equivalent-fractions-worked1","kind":"worked","src":"stop:equivalent-fractions#worked1","title":"Worked out — Same share, different pieces: Missing bottom","body":"2/3 = 8/?: 2 × what makes 8? → 4 · Same to the bottom: 3 × 4 → 12","cta":"Watch it step by step","level":5,"route":"#/stop/equivalent-fractions"},"worked-equivalent-fractions-worked2":{"id":"worked-equivalent-fractions-worked2","kind":"worked","src":"stop:equivalent-fractions#worked2","title":"Worked out — Same share, different pieces: Going down: dividing","body":"10/15 = ?/3: 15 ÷ what makes 3? → 5 · Same to the top: 10 ÷ 5 → 2","cta":"Watch it step by step","level":5,"route":"#/stop/equivalent-fractions"},"why-equivalent-fractions-why2":{"id":"why-equivalent-fractions-why2","kind":"why","src":"stop:equivalent-fractions#why2","title":"Why “Same share, different pieces” works","body":"It works backwards too. 9/12 can be glued back into bigger pieces by dividing top and bottom by the same number. Multiply or divide — as long as it is the same number, top and bottom, the share never changes.","cta":"See why","level":5,"route":"#/stop/equivalent-fractions"},"moment-equivalent-fractions-beat3":{"id":"moment-equivalent-fractions-beat3","kind":"moment","src":"story:equivalent-fractions#beat3","badge":{"id":"story","label":"A story"},"title":"Smaller slices — on the notepad","body":"Rafi: And your 3 quarters become… 3 × 3 = 9","cta":"Read the story","level":5,"route":"#/stop/equivalent-fractions"},"try-equivalent-fractions-L5":{"id":"try-equivalent-fractions-L5","kind":"try","level":5,"src":"try:equivalent-fractions@5/2#0","title":"Same share, different pieces — your turn","route":"#/stop/equivalent-fractions","cta":"Practise this stop","play":{"q":"4/5 = 8/?","opts":["10","2","11"],"after":"Whatever you do to the bottom, do the same to the top."}},"hook-compare-fractions-hook":{"id":"hook-compare-fractions-hook","kind":"hook","src":"stop:compare-fractions#hook","title":"Can you? — Which slice is bigger?","body":"3/5 or 4/7 — which is more cake?","cta":"Find out how","level":5,"route":"#/stop/compare-fractions"},"worked-compare-fractions-worked0":{"id":"worked-compare-fractions-worked0","kind":"worked","src":"stop:compare-fractions#worked0","title":"Worked out — Which slice is bigger?: Same bottoms","body":"5/8  ?  3/8: Same-size pieces. How many on the left? → 5 · …and on the right? → 3 · Compare → >","cta":"Watch it step by step","level":5,"route":"#/stop/compare-fractions"},"worked-compare-fractions-worked1":{"id":"worked-compare-fractions-worked1","kind":"worked","src":"stop:compare-fractions#worked1","title":"Worked out — Which slice is bigger?: Same tops","body":"2/5  ?  2/7: Same number of pieces. Which cut makes bigger pieces: 5 or 7? → 5 · Compare → >","cta":"Watch it step by step","level":5,"route":"#/stop/compare-fractions"},"worked-compare-fractions-worked2":{"id":"worked-compare-fractions-worked2","kind":"worked","src":"stop:compare-fractions#worked2","title":"Worked out — Which slice is bigger?: Nothing matches","body":"3/5  ?  4/7: 3 × 7 → 21 · 4 × 5 → 20 · Compare → >","cta":"Watch it step by step","level":5,"route":"#/stop/compare-fractions"},"worked-compare-fractions-worked3":{"id":"worked-compare-fractions-worked3","kind":"worked","src":"stop:compare-fractions#worked3","title":"Worked out — Which slice is bigger?: Equal after all","body":"2/4  ?  3/6: 2 × 6 → 12 · 3 × 4 → 12 · Compare → =","cta":"Watch it step by step","level":5,"route":"#/stop/compare-fractions"},"why-compare-fractions-why2":{"id":"why-compare-fractions-why2","kind":"why","src":"stop:compare-fractions#why2","title":"Why “Which slice is bigger?” works","body":"If nothing matches, cut both into the same pieces. 3/5 and 4/7 both become thirty-fifths: 3/5 = 21/35 and 4/7 = 20/35. You never need the 35 — the two new tops, 3 × 7 and 4 × 5, are all you compare. That is cross-multiplying. If the two new tops come out the same, the fractions are equal: two names for one share, like 2/4 and 3/6.","cta":"See why","level":5,"route":"#/stop/compare-fractions"},"moment-compare-fractions-beat4":{"id":"moment-compare-fractions-beat4","kind":"moment","src":"story:compare-fractions#beat4","badge":{"id":"story","label":"A story"},"title":"Two birthday cakes — on the notepad","body":"Theo: Chocolate: 4 times 5. 4 × 5 = 20","cta":"Read the story","level":5,"route":"#/stop/compare-fractions"},"try-compare-fractions-L5":{"id":"try-compare-fractions-L5","kind":"try","level":5,"src":"try:compare-fractions@5/2#0","title":"Which slice is bigger? — your turn","route":"#/stop/compare-fractions","cta":"Practise this stop","play":{"q":"1/7  ?  1/5","opts":["<","=",">"],"after":"Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply."}},"trick-best-buy-idea":{"id":"trick-best-buy-idea","kind":"trick","src":"stop:best-buy#idea","title":"The best buy","body":"Find the price of ONE from each pack — or of the same number from each — then compare like with like. A bigger pack costs more, so the prices on their own tell you nothing. What matters is what each apple costs. 28 ÷ 4 is 7 coins an apple; 36 ÷ 6 is 6 coins an apple. The bigger pack is the better buy — this time.","cta":"Learn the trick","level":5,"route":"#/stop/best-buy"},"story-best-buy-open":{"id":"story-best-buy-open","kind":"story","src":"story:best-buy#open","badge":{"id":"story","label":"A story"},"title":"Two bags of apples","body":"At the fruit stall, a bag of 4 apples is 28 coins and a bag of 6 apples is 36 coins. — with Ines and Pip.","art":"art/s-market.webp","cta":"Read the story","level":5,"route":"#/stop/best-buy"},"hook-best-buy-hook":{"id":"hook-best-buy-hook","kind":"hook","src":"stop:best-buy#hook","title":"Can you? — The best buy","body":"4 apples for 28 coins, or 6 apples for 36 coins. Which is cheaper for each apple?","cta":"Find out how","level":5,"route":"#/stop/best-buy"},"idea-best-buy-case0":{"id":"idea-best-buy-case0","kind":"idea","src":"stop:best-buy#case0","title":"The best buy: Price of one","body":"Both prices share out evenly, so find what ONE costs from each pack and compare.","cta":"See it worked","level":5,"route":"#/stop/best-buy"},"worked-best-buy-worked0":{"id":"worked-best-buy-worked0","kind":"worked","src":"stop:best-buy#worked0","title":"Worked out — The best buy: Price of one","body":"Pack A: 4 apples for 28 coins. Pack B: 6 apples for 36 coins. Which is cheaper for each apple?: One from A: 28 ÷ 4 → 7 · One from B: 36 ÷ 6 → 6 · Which is cheaper each? → Pack B","cta":"Watch it step by step","level":5,"route":"#/stop/best-buy"},"idea-best-buy-case1":{"id":"idea-best-buy-case1","kind":"idea","src":"stop:best-buy#case1","title":"The best buy: Price of the same number","body":"One would be a messy number, so price the same number from both packs — a number both pack sizes go into.","cta":"See it worked","level":5,"route":"#/stop/best-buy"},"worked-best-buy-worked1":{"id":"worked-best-buy-worked1","kind":"worked","src":"stop:best-buy#worked1","title":"Worked out — The best buy: Price of the same number","body":"Pack A: 5 pencils for 12 coins. Pack B: 3 pencils for 8 coins. Which is cheaper for each pencil?: 15 from A: 12 × 3 → 36 · 15 from B: 8 × 5 → 40 · Which is cheaper each? → Pack A","cta":"Watch it step by step","level":5,"route":"#/stop/best-buy"},"why-best-buy-why1":{"id":"why-best-buy-why1","kind":"why","src":"stop:best-buy#why1","title":"Why “The best buy” works","body":"Sometimes one apple works out to a messy number. Then price the SAME number from both packs instead. 5 for 12 and 3 for 8: 15 apples from the first pack is 3 lots, 36 coins; 15 from the second is 5 lots, 40 coins. The first is cheaper, and nobody had to divide.","cta":"See why","level":5,"route":"#/stop/best-buy"},"why-best-buy-why2":{"id":"why-best-buy-why2","kind":"why","src":"stop:best-buy#why2","title":"Why “The best buy” works","body":"Cheaper each is not always better for you — ten apples you will not eat are not a bargain. The maths tells you the price; you still decide what you need.","cta":"See why","level":5,"route":"#/stop/best-buy"},"algebra-best-buy-alg":{"id":"algebra-best-buy-alg","kind":"algebra","src":"stop:best-buy#alg","title":"The algebra behind “The best buy”","body":"A is the better buy when priceA ÷ countA < priceB ÷ countB (or priceA × countB < priceB × countA)","cta":"See why","level":5,"route":"#/stop/best-buy"},"moment-best-buy-beat3":{"id":"moment-best-buy-beat3","kind":"moment","src":"story:best-buy#beat3","badge":{"id":"story","label":"A story"},"title":"Two bags of apples — on the notepad","body":"Pip: And the big bag… 36 ÷ 6 = 6","cta":"Read the story","level":5,"route":"#/stop/best-buy"},"moral-best-buy-beat5":{"id":"moral-best-buy-beat5","kind":"moral","src":"story:best-buy#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “Two bags of apples”","body":"The big bag, then — as long as we eat all six.","cta":"Read the story","level":5,"route":"#/stop/best-buy"},"try-best-buy-L5":{"id":"try-best-buy-L5","kind":"try","level":5,"src":"try:best-buy@5/1#0","title":"The best buy — your turn","route":"#/stop/best-buy","cta":"Practise this stop","play":{"q":"Pack A: 2 samosas for 12 coins. Pack B: 5 samosas for 25 coins. Which is cheaper for each samosa?","opts":["Pack B","Pack A"],"after":"Find the price of ONE from each pack — or of the same number from each — then compare like with like."}},"trick-fraction-off-idea":{"id":"trick-fraction-off-idea","kind":"trick","src":"stop:fraction-off#idea","title":"A sale","body":"Find the fraction of the price that comes off, then take it away from the price. \"1/4 off\" means the price is cut into 4 equal parts and one part is taken away. One quarter of 40 is 40 ÷ 4 = 10, so 10 coins come off and the kite costs 30.","cta":"Learn the trick","level":5,"route":"#/stop/fraction-off"},"story-fraction-off-open":{"id":"story-fraction-off-open","kind":"story","src":"story:fraction-off#open","badge":{"id":"story","label":"A story"},"title":"The sale sign","body":"In the sports shop, a 40-coin kite has a sign on it: 1/4 off. — with Nova and Rafi.","art":"art/s-shop.webp","cta":"Read the story","level":5,"route":"#/stop/fraction-off"},"hook-fraction-off-hook":{"id":"hook-fraction-off-hook","kind":"hook","src":"stop:fraction-off#hook","title":"Can you? — A sale","body":"A 40-coin kite has 1/4 off in the sale. What does it cost now?","cta":"Find out how","level":5,"route":"#/stop/fraction-off"},"idea-fraction-off-case0":{"id":"idea-fraction-off-case0","kind":"idea","src":"stop:fraction-off#case0","title":"A sale: One part off","body":"With 1 on top, one share comes off: divide the price by the bottom number, then take that away.","cta":"See it worked","level":5,"route":"#/stop/fraction-off"},"worked-fraction-off-worked0":{"id":"worked-fraction-off-worked0","kind":"worked","src":"stop:fraction-off#worked0","title":"Worked out — A sale: One part off","body":"A 40-coin kite has 1/4 off in the sale. What does it cost now?: 1/4 of 40: 40 ÷ 4 → 10 · Take it off: 40 − 10 → 30","cta":"Watch it step by step","level":5,"route":"#/stop/fraction-off"},"idea-fraction-off-case1":{"id":"idea-fraction-off-case1","kind":"idea","src":"stop:fraction-off#case1","title":"A sale: Several parts off","body":"Find one share, multiply by the top number to get the whole discount, then take it off the price.","cta":"See it worked","level":5,"route":"#/stop/fraction-off"},"worked-fraction-off-worked1":{"id":"worked-fraction-off-worked1","kind":"worked","src":"stop:fraction-off#worked1","title":"Worked out — A sale: Several parts off","body":"A 40-coin puzzle has 2/5 off in the sale. What does it cost now?: 1/5 of 40: 40 ÷ 5 → 8 · 2/5 off: 8 × 2 → 16 · Take it off: 40 − 16 → 24","cta":"Watch it step by step","level":5,"route":"#/stop/fraction-off"},"why-fraction-off-why1":{"id":"why-fraction-off-why1","kind":"why","src":"stop:fraction-off#why1","title":"Why “A sale” works","body":"For 2/5 off, find one fifth and double it: 2/5 of 40 is 8 × 2 = 16 off, so it costs 24. The bar shows the shaded parts that come off and the plain parts you still pay.","cta":"See why","level":5,"route":"#/stop/fraction-off"},"why-fraction-off-why2":{"id":"why-fraction-off-why2","kind":"why","src":"stop:fraction-off#why2","title":"Why “A sale” works","body":"You can also count the parts you DO pay: with 1/4 off you pay 3/4 of the price, and 3/4 of 40 is 30. Same answer by a different road — a good way to check. A sale lowers the price, but it is only a saving if you wanted the thing anyway.","cta":"See why","level":5,"route":"#/stop/fraction-off"},"algebra-fraction-off-alg":{"id":"algebra-fraction-off-alg","kind":"algebra","src":"stop:fraction-off#alg","title":"The algebra behind “A sale”","body":"price with k/d off = price − price ÷ d × k = price ÷ d × (d − k)","cta":"See why","level":5,"route":"#/stop/fraction-off"},"moment-fraction-off-beat2":{"id":"moment-fraction-off-beat2","kind":"moment","src":"story:fraction-off#beat2","badge":{"id":"story","label":"A story"},"title":"The sale sign — on the notepad","body":"Nova: One part comes off. Take it away from the price. 40 − 10 = 30","cta":"Read the story","level":5,"route":"#/stop/fraction-off"},"moral-fraction-off-beat4":{"id":"moral-fraction-off-beat4","kind":"moral","src":"story:fraction-off#beat4","badge":{"id":"story","label":"A story"},"title":"Nova, in “The sale sign”","body":"Same answer both ways. 30 coins.","cta":"Read the story","level":5,"route":"#/stop/fraction-off"},"try-fraction-off-L5":{"id":"try-fraction-off-L5","kind":"try","level":5,"src":"try:fraction-off@5/1#0","title":"A sale — your turn","route":"#/stop/fraction-off","cta":"Practise this stop","play":{"q":"A 100-coin football has 1/10 off in the sale. What does it cost now?","opts":["90","10","91"],"after":"Find the fraction of the price that comes off, then take it away from the price."}},"trick-profit-and-loss-idea":{"id":"trick-profit-and-loss-idea","kind":"trick","src":"stop:profit-and-loss#idea","title":"Profit and loss","body":"Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit. The coins that come in from selling are the takings: 14 cups at 4 coins each is 56 coins. But the stall did not get those lemons free — 30 coins went out first. Profit is what is left after paying for everything: 56 − 30 = 26.","cta":"Learn the trick","level":5,"route":"#/stop/profit-and-loss"},"story-profit-and-loss-open":{"id":"story-profit-and-loss-open","kind":"story","src":"story:profit-and-loss#open","badge":{"id":"story","label":"A story"},"title":"The lemonade stall","body":"At the street festival, Dax and Ines run a lemonade stall. Lemons and sugar cost 30 coins. — with Ines and Dax.","art":"art/s-festival.webp","cta":"Read the story","level":5,"route":"#/stop/profit-and-loss"},"hook-profit-and-loss-hook":{"id":"hook-profit-and-loss-hook","kind":"hook","src":"stop:profit-and-loss#hook","title":"Can you? — Profit and loss","body":"A lemonade stall spends 30 coins on lemons and sugar and sells 14 cups at 4 coins each. What is the profit?","cta":"Find out how","level":5,"route":"#/stop/profit-and-loss"},"idea-profit-and-loss-case0":{"id":"idea-profit-and-loss-case0","kind":"idea","src":"stop:profit-and-loss#case0","title":"Profit and loss: A profit","body":"Work out the takings first — how many sold times the price — then take away what was spent.","cta":"See it worked","level":5,"route":"#/stop/profit-and-loss"},"worked-profit-and-loss-worked0":{"id":"worked-profit-and-loss-worked0","kind":"worked","src":"stop:profit-and-loss#worked0","title":"Worked out — Profit and loss: A profit","body":"A lemonade stall spends 30 coins on lemons and sugar, then sells 14 cups at 4 coins each. What is the profit?: Takings: 14 × 4 → 56 · Profit: 56 − 30 → 26","cta":"Watch it step by step","level":5,"route":"#/stop/profit-and-loss"},"idea-profit-and-loss-case1":{"id":"idea-profit-and-loss-case1","kind":"idea","src":"stop:profit-and-loss#case1","title":"Profit and loss: Two costs to pay","body":"Everything that went out counts: add the materials and the pitch together before you take them away.","cta":"See it worked","level":5,"route":"#/stop/profit-and-loss"},"worked-profit-and-loss-worked1":{"id":"worked-profit-and-loss-worked1","kind":"worked","src":"stop:profit-and-loss#worked1","title":"Worked out — Profit and loss: Two costs to pay","body":"A bake stall spends 20 coins on flour and butter and pays 10 coins for its pitch, then sells 12 biscuits at 5 coins each. What is the profit? (Write a loss as a negative number.): Takings: 12 × 5 → 60 · Everything spent: 20 + 10 → 30 · Profit: 60 − 30 → 30","cta":"Watch it step by step","level":5,"route":"#/stop/profit-and-loss"},"idea-profit-and-loss-case2":{"id":"idea-profit-and-loss-case2","kind":"idea","src":"stop:profit-and-loss#case2","title":"Profit and loss: A loss","body":"More went out than came in, so the profit is below zero. Write it with a minus sign: that is a loss.","cta":"See it worked","level":5,"route":"#/stop/profit-and-loss"},"worked-profit-and-loss-worked2":{"id":"worked-profit-and-loss-worked2","kind":"worked","src":"stop:profit-and-loss#worked2","title":"Worked out — Profit and loss: A loss","body":"A badge stall spends 50 coins on pins and card and pays 15 coins for its pitch, then sells 10 badges at 6 coins each. What is the profit? (Write a loss as a negative number.): Takings: 10 × 6 → 60 · Everything spent: 50 + 15 → 65 · Profit: 60 − 65 → -5","cta":"Watch it step by step","level":5,"route":"#/stop/profit-and-loss"},"idea-profit-and-loss-case3":{"id":"idea-profit-and-loss-case3","kind":"idea","src":"stop:profit-and-loss#case3","title":"Profit and loss: Breaking even","body":"The takings exactly cover the costs. Nothing gained, nothing lost: the profit is 0.","cta":"See it worked","level":5,"route":"#/stop/profit-and-loss"},"worked-profit-and-loss-worked3":{"id":"worked-profit-and-loss-worked3","kind":"worked","src":"stop:profit-and-loss#worked3","title":"Worked out — Profit and loss: Breaking even","body":"A plant stall spends 30 coins on pots and soil and pays 10 coins for its pitch, then sells 8 seedlings at 5 coins each. What is the profit? (Write a loss as a negative number.): Takings: 8 × 5 → 40 · Everything spent: 30 + 10 → 40 · Profit: 40 − 40 → 0","cta":"Watch it step by step","level":5,"route":"#/stop/profit-and-loss"},"why-profit-and-loss-why1":{"id":"why-profit-and-loss-why1","kind":"why","src":"stop:profit-and-loss#why1","title":"Why “Profit and loss” works","body":"Takings are not profit. A stall that takes 56 coins and spent 60 has made a loss of 4. Writing that as −4 keeps one rule for both: profit = in − out, and the sign says which way it went. If there is more than one cost — materials and a pitch — add all the costs first. And if the takings exactly match the costs, the profit is 0: the stall has broken even.","cta":"See why","level":5,"route":"#/stop/profit-and-loss"},"why-profit-and-loss-why2":{"id":"why-profit-and-loss-why2","kind":"why","src":"stop:profit-and-loss#why2","title":"Why “Profit and loss” works","body":"A loss is not a disaster, it is information — it tells the stall-keeper to change the price, the costs or how many they make. Every business uses this one subtraction to decide what to do next.","cta":"See why","level":5,"route":"#/stop/profit-and-loss"},"algebra-profit-and-loss-alg":{"id":"algebra-profit-and-loss-alg","kind":"algebra","src":"stop:profit-and-loss#alg","title":"The algebra behind “Profit and loss”","body":"profit = number sold × price − costs  (negative means a loss)","cta":"See why","level":5,"route":"#/stop/profit-and-loss"},"moment-profit-and-loss-beat3":{"id":"moment-profit-and-loss-beat3","kind":"moment","src":"story:profit-and-loss#beat3","badge":{"id":"story","label":"A story"},"title":"The lemonade stall — on the notepad","body":"Ines: We took in 56. But 30 went out first, on lemons. Profit is in minus out. 56 − 30 = 26","cta":"Read the story","level":5,"route":"#/stop/profit-and-loss"},"moral-profit-and-loss-beat5":{"id":"moral-profit-and-loss-beat5","kind":"moral","src":"story:profit-and-loss#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The lemonade stall”","body":"And now we know what a cup costs us to make — so we can price it next time.","cta":"Read the story","level":5,"route":"#/stop/profit-and-loss"},"try-profit-and-loss-L5":{"id":"try-profit-and-loss-L5","kind":"try","level":5,"src":"try:profit-and-loss@5/1#0","title":"Profit and loss — your turn","route":"#/stop/profit-and-loss","cta":"Practise this stop","play":{"q":"A bracelet stall spends 42 coins on beads and thread, then sells 10 bracelets at 5 coins each. What is the profit?","opts":["8","50","9"],"after":"Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit."}},"trick-angles-on-a-line-idea":{"id":"trick-angles-on-a-line-idea","kind":"trick","src":"stop:angles-on-a-line#idea","title":"Angles on a line and round a point","body":"Angles on a straight line add up to 180°; angles all the way round a point add up to 360°. Take away the ones you know. A straight line is half a turn. Stand on the point facing along the line and turn until you face back the other way: that is 180°. Each angle on the line is one part of that same half-turn, so the parts must add up to 180°.","cta":"Learn the trick","level":5,"route":"#/stop/angles-on-a-line"},"story-angles-on-a-line-open":{"id":"story-angles-on-a-line-open","kind":"story","src":"story:angles-on-a-line#open","badge":{"id":"story","label":"A story"},"title":"The see-saw","body":"A ramp leans on a flat path by the stadium. On one side it makes an angle of 125° with the path. — with Theo and Ines.","art":"art/s-stadium.webp","cta":"Read the story","level":5,"route":"#/stop/angles-on-a-line"},"idea-angles-on-a-line-case0":{"id":"idea-angles-on-a-line-case0","kind":"idea","src":"stop:angles-on-a-line#case0","title":"Angles on a line and round a point: On a straight line","body":"A straight line is half a turn, so the angles along it share 180° between them.","cta":"See it worked","level":5,"route":"#/stop/angles-on-a-line"},"idea-angles-on-a-line-case1":{"id":"idea-angles-on-a-line-case1","kind":"idea","src":"stop:angles-on-a-line#case1","title":"Angles on a line and round a point: Round a point","body":"All the way round is a whole turn, 360°. Add every angle you know first, then see what is left.","cta":"See it worked","level":5,"route":"#/stop/angles-on-a-line"},"why-angles-on-a-line-why1":{"id":"why-angles-on-a-line-why1","kind":"why","src":"stop:angles-on-a-line#why1","title":"Why “Angles on a line and round a point” works","body":"All the way round a point is a whole turn — you end up facing where you started — and a whole turn is 360°. However many angles the rays cut it into, together they are the full 360°.","cta":"See why","level":5,"route":"#/stop/angles-on-a-line"},"algebra-angles-on-a-line-alg":{"id":"algebra-angles-on-a-line-alg","kind":"algebra","src":"stop:angles-on-a-line#alg","title":"The algebra behind “Angles on a line and round a point”","body":"a + b = 180° on a line · a + b + c + … = 360° round a point","cta":"See why","level":5,"route":"#/stop/angles-on-a-line"},"moral-angles-on-a-line-beat6":{"id":"moral-angles-on-a-line-beat6","kind":"moral","src":"story:angles-on-a-line#beat6","badge":{"id":"story","label":"A story"},"title":"Theo, in “The see-saw”","body":"So the missing angle is 55°.","cta":"Read the story","level":5,"route":"#/stop/angles-on-a-line"},"try-angles-on-a-line-L5":{"id":"try-angles-on-a-line-L5","kind":"try","level":5,"src":"try:angles-on-a-line@5/1#0","title":"Angles on a line and round a point — your turn","route":"#/stop/angles-on-a-line","cta":"Practise this stop","play":{"q":"Angles on a straight line: 105° and ?. Find the missing angle.","opts":["75","180","105"],"after":"Angles on a straight line add up to 180°; angles all the way round a point add up to 360°. Take away the ones you know."}},"trick-divisible-4-8-idea":{"id":"trick-divisible-4-8-idea","kind":"trick","src":"stop:divisible-4-8#idea","title":"Tests for 4 and 8","body":"For 4, test just the last two digits. For 8, the last three. 100 is 4 × 25, so every whole hundred divides by 4. 73,516 is 73,500 + 16, and the 73,500 is a whole number of hundreds — it takes care of itself. Only the 16 is left to check, and 16 = 4 × 4.","cta":"Learn the trick","level":5,"route":"#/stop/divisible-4-8"},"story-divisible-4-8-open":{"id":"story-divisible-4-8-open","kind":"story","src":"story:divisible-4-8#open","badge":{"id":"story","label":"A story"},"title":"The seed packets","body":"The seed library has 73,516 seeds to share into packets of 4. — with Rafi and Suki.","art":"art/s-garden.webp","cta":"Read the story","level":5,"route":"#/stop/divisible-4-8"},"hook-divisible-4-8-hook":{"id":"hook-divisible-4-8-hook","kind":"hook","src":"stop:divisible-4-8#hook","title":"Can you? — Tests for 4 and 8","body":"Is 73,516 in the 4 times table? No long division.","cta":"Find out how","level":5,"route":"#/stop/divisible-4-8"},"idea-divisible-4-8-case0":{"id":"idea-divisible-4-8-case0","kind":"idea","src":"stop:divisible-4-8#case0","title":"Tests for 4 and 8: Divisible by 4","body":"Every hundred splits into fours, so only the last TWO digits decide.","cta":"See it worked","level":5,"route":"#/stop/divisible-4-8"},"worked-divisible-4-8-worked0":{"id":"worked-divisible-4-8-worked0","kind":"worked","src":"stop:divisible-4-8#worked0","title":"Worked out — Tests for 4 and 8: Divisible by 4","body":"Is 73,516 divisible by 4?: The last two digits of 73,516 → 16 · Is 16 in the 4 times table? → Yes","cta":"Watch it step by step","level":5,"route":"#/stop/divisible-4-8"},"idea-divisible-4-8-case1":{"id":"idea-divisible-4-8-case1","kind":"idea","src":"stop:divisible-4-8#case1","title":"Tests for 4 and 8: Divisible by 8","body":"A hundred does not split into eights, but a thousand does — so look at the last THREE digits. Passing the test for 4 is not enough.","cta":"See it worked","level":5,"route":"#/stop/divisible-4-8"},"worked-divisible-4-8-worked1":{"id":"worked-divisible-4-8-worked1","kind":"worked","src":"stop:divisible-4-8#worked1","title":"Worked out — Tests for 4 and 8: Divisible by 8","body":"Is 73,516 divisible by 8?: The last three digits of 73,516 → 516 · Is 516 in the 8 times table? (Can you halve it three times and stay whole?) → No","cta":"Watch it step by step","level":5,"route":"#/stop/divisible-4-8"},"why-divisible-4-8-why1":{"id":"why-divisible-4-8-why1","kind":"why","src":"stop:divisible-4-8#why1","title":"Why “Tests for 4 and 8” works","body":"For 8 you need one more digit, because 100 does not divide by 8 but 1000 does: 1000 = 8 × 125. So every whole thousand divides by 8, and only the last three digits decide.","cta":"See why","level":5,"route":"#/stop/divisible-4-8"},"why-divisible-4-8-why2":{"id":"why-divisible-4-8-why2","kind":"why","src":"stop:divisible-4-8#why2","title":"Why “Tests for 4 and 8” works","body":"The pattern goes on: 2 needs the last digit, 4 the last two, 8 the last three — because 10 is 2 × 5, 100 is 4 × 25 and 1000 is 8 × 125.","cta":"See why","level":5,"route":"#/stop/divisible-4-8"},"algebra-divisible-4-8-alg":{"id":"algebra-divisible-4-8-alg","kind":"algebra","src":"stop:divisible-4-8#alg","title":"The algebra behind “Tests for 4 and 8”","body":"4 | 100 ⇒ test n mod 100 ; 8 | 1000 ⇒ test n mod 1000","cta":"See why","level":5,"route":"#/stop/divisible-4-8"},"moment-divisible-4-8-beat3":{"id":"moment-divisible-4-8-beat3","kind":"moment","src":"story:divisible-4-8#beat3","badge":{"id":"story","label":"A story"},"title":"The seed packets — on the notepad","body":"Rafi: 16 is four fours. So yes, it splits exactly. 16 ÷ 4 = 4","cta":"Read the story","level":5,"route":"#/stop/divisible-4-8"},"moral-divisible-4-8-beat5":{"id":"moral-divisible-4-8-beat5","kind":"moral","src":"story:divisible-4-8#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The seed packets”","body":"And 73,516 in packets of 4 makes…","cta":"Read the story","level":5,"route":"#/stop/divisible-4-8"},"try-divisible-4-8-L5":{"id":"try-divisible-4-8-L5","kind":"try","level":5,"src":"try:divisible-4-8@5/1#0","title":"Tests for 4 and 8 — your turn","route":"#/stop/divisible-4-8","cta":"Practise this stop","play":{"q":"Is 57,708 divisible by 4?","opts":["Yes","No"],"after":"For 4, test just the last two digits. For 8, the last three."}},"trick-prime-or-not-idea":{"id":"trick-prime-or-not-idea","kind":"trick","src":"stop:prime-or-not#idea","title":"Is it prime?","body":"Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime. A prime has exactly two factors: 1 and itself. 7 is prime — seven dots only make one rectangle, a single row. 1 is not prime, because it has only one factor.","cta":"Learn the trick","level":5,"route":"#/stop/prime-or-not"},"story-prime-or-not-open":{"id":"story-prime-or-not-open","kind":"story","src":"story:prime-or-not#open","badge":{"id":"story","label":"A story"},"title":"The sieve","body":"On a camping night, Theo asks Vesper: is 91 prime? It is odd, it does not end in 5, and its digits add to 10. — with Vesper and Theo.","art":"art/s-night.webp","cta":"Read the story","level":5,"route":"#/stop/prime-or-not"},"hook-prime-or-not-hook":{"id":"hook-prime-or-not-hook","kind":"hook","src":"stop:prime-or-not#hook","title":"Can you? — Is it prime?","body":"91 — odd, does not end in 5, digits do not add to a multiple of 3. Prime?","cta":"Find out how","level":5,"route":"#/stop/prime-or-not"},"idea-prime-or-not-case0":{"id":"idea-prime-or-not-case0","kind":"idea","src":"stop:prime-or-not#case0","title":"Is it prime?: Not prime","body":"As soon as one prime divides it exactly, you can stop: it is not prime. 91 looks prime, but 7 goes in.","cta":"See it worked","level":5,"route":"#/stop/prime-or-not"},"worked-prime-or-not-worked0":{"id":"worked-prime-or-not-worked0","kind":"worked","src":"stop:prime-or-not#worked0","title":"Worked out — Is it prime?: Not prime","body":"Is 91 prime?: Which whole number, times itself, is the last one at or below 91? Test only up to it → 9 · The smallest number bigger than 1 that divides 91 exactly → 7 · 7 divides it — so is it prime? → Not prime","cta":"Watch it step by step","level":5,"route":"#/stop/prime-or-not"},"idea-prime-or-not-case1":{"id":"idea-prime-or-not-case1","kind":"idea","src":"stop:prime-or-not#case1","title":"Is it prime?: Prime","body":"To say \"prime\" you must try EVERY prime up to the square-root line and see each one fail. For 97 that is 2, 3, 5 and 7.","cta":"See it worked","level":5,"route":"#/stop/prime-or-not"},"why-prime-or-not-why1":{"id":"why-prime-or-not-why1","kind":"why","src":"stop:prime-or-not#why1","title":"Why “Is it prime?” works","body":"Factors come in pairs that meet in the middle, so if a number has a factor bigger than its square root, the partner is smaller than it — and you would already have found the partner. For 91 you only need to try up to 9, because 10 × 10 is already 100. And 7 × 13 = 91, so 91 is not prime.","cta":"See why","level":5,"route":"#/stop/prime-or-not"},"why-prime-or-not-why2":{"id":"why-prime-or-not-why2","kind":"why","src":"stop:prime-or-not#why2","title":"Why “Is it prime?” works","body":"You only need to try primes, because any other number is built from primes: if 6 divided 91, then 2 would too. This is the idea of the Sieve: write out the numbers, cross out every multiple of 2, then of 3, then of 5, of 7… Whatever is never crossed out is prime.","cta":"See why","level":5,"route":"#/stop/prime-or-not"},"algebra-prime-or-not-alg":{"id":"algebra-prime-or-not-alg","kind":"algebra","src":"stop:prime-or-not#alg","title":"The algebra behind “Is it prime?”","body":"n is prime ⇔ n > 1 and no prime p ≤ √n divides n","cta":"See why","level":5,"route":"#/stop/prime-or-not"},"moment-prime-or-not-beat3":{"id":"moment-prime-or-not-beat3","kind":"moment","src":"story:prime-or-not#beat3","badge":{"id":"story","label":"A story"},"title":"The sieve — on the notepad","body":"Theo: Seven thirteens… that’s 91! 7 × 13 = 91","cta":"Read the story","level":5,"route":"#/stop/prime-or-not"},"moral-prime-or-not-beat5":{"id":"moral-prime-or-not-beat5","kind":"moral","src":"story:prime-or-not#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “The sieve”","body":"Next time I’ll try every prime up to there, and check them all.","cta":"Read the story","level":5,"route":"#/stop/prime-or-not"},"try-prime-or-not-L5":{"id":"try-prime-or-not-L5","kind":"try","level":5,"src":"try:prime-or-not@5/1#0","title":"Is it prime? — your turn","route":"#/stop/prime-or-not","cta":"Practise this stop","play":{"q":"Is 16 prime?","opts":["Not prime","Prime"],"after":"Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime."}},"trick-square-five-idea":{"id":"trick-square-five-idea","kind":"trick","src":"stop:square-five#idea","title":"Squaring numbers that end in 5","body":"Take the front digit, multiply it by the next number up, and write 25 on the end. 35 × 35: the front digit is 3, one more than it is 4, and 3 × 4 = 12. Write 25 after it: 1225.","cta":"Learn the trick","level":5,"route":"#/stop/square-five"},"story-square-five-open":{"id":"story-square-five-open","kind":"story","src":"story:square-five#open","badge":{"id":"story","label":"A story"},"title":"Mira's square flowerbed","body":"Mira is planting a square flowerbed: 35 bulbs along each side. — with Mira and Dax.","art":"art/s-garden.webp","cta":"Read the story","level":5,"route":"#/stop/square-five"},"hook-square-five-hook":{"id":"hook-square-five-hook","kind":"hook","src":"stop:square-five#hook","title":"Can you? — Squaring numbers that end in 5","body":"35 × 35 — in your head, in three seconds.","cta":"Find out how","level":5,"route":"#/stop/square-five"},"worked-square-five-worked0":{"id":"worked-square-five-worked0","kind":"worked","src":"stop:square-five#worked0","title":"Worked out — Squaring numbers that end in 5","body":"35²: 3 × 4 → 12 · Write 25 on the end → 1225","cta":"Watch it step by step","level":5,"route":"#/stop/square-five"},"why-square-five-why1":{"id":"why-square-five-why1","kind":"why","src":"stop:square-five#why1","title":"Why “Squaring numbers that end in 5” works","body":"It works for every number ending in 5, always. A number ending in 5 is ten lots of something, plus 5. Square it and the middle always lands exactly on a whole number of hundreds — n lots of (n + 1) hundreds — and the 5 × 5 on the end is always 25.","cta":"See why","level":5,"route":"#/stop/square-five"},"algebra-square-five-alg":{"id":"algebra-square-five-alg","kind":"algebra","src":"stop:square-five#alg","title":"The algebra behind “Squaring numbers that end in 5”","body":"(10n + 5)² = 100·n(n + 1) + 25","cta":"See why","level":5,"route":"#/stop/square-five"},"sutra-square-five-sutra":{"id":"sutra-square-five-sutra","kind":"sutra","src":"stop:square-five#sutra","title":"Ekādhikena Pūrvena","body":"“by one more than the one before” — the sutra behind Squaring numbers that end in 5.","cta":"Open the stop","level":5,"route":"#/stop/square-five"},"moment-square-five-beat2":{"id":"moment-square-five-beat2","kind":"moment","src":"story:square-five#beat2","badge":{"id":"story","label":"A story"},"title":"Mira's square flowerbed — on the notepad","body":"Mira: No need. The front digit is 3, and one more than 3 is 4. 3 × 4 = 12","cta":"Read the story","level":5,"route":"#/stop/square-five"},"moral-square-five-beat5":{"id":"moral-square-five-beat5","kind":"moral","src":"story:square-five#beat5","badge":{"id":"story","label":"A story"},"title":"Mira, in “Mira's square flowerbed”","body":"For every number that ends in 5. The Observatory will show you why.","cta":"Read the story","level":5,"route":"#/stop/square-five"},"try-square-five-L5":{"id":"try-square-five-L5","kind":"try","level":5,"src":"try:square-five@5/1#0","title":"Squaring numbers that end in 5 — your turn","route":"#/stop/square-five","cta":"Practise this stop","play":{"q":"65² = ?","opts":["4225","42","4226"],"after":"Take the front digit, multiply it by the next number up, and write 25 on the end."}},"trick-square-dots-idea":{"id":"trick-square-dots-idea","kind":"trick","src":"stop:square-dots#idea","title":"What a square number is","body":"n² means n rows of n. Lay them out and they make a perfect square. Put 7 counters in a row, then make 7 rows like it. The shape is exactly as tall as it is wide: a square. There are 7 × 7 = 49 counters, so 49 is a square number, and we write 7 × 7 as 7² — \"seven squared\".","cta":"Learn the trick","level":5,"route":"#/stop/square-dots"},"story-square-dots-open":{"id":"story-square-dots-open","kind":"story","src":"story:square-dots#open","badge":{"id":"story","label":"A story"},"title":"The parade ground","body":"Morning at the Square Palace. The guards line up on the parade ground: 7 rows, 7 guards in every row. — with Mira and Pip.","art":"art/s-palace.webp","cta":"Read the story","level":5,"route":"#/stop/square-dots"},"worked-square-dots-worked0":{"id":"worked-square-dots-worked0","kind":"worked","src":"stop:square-dots#worked0","title":"Worked out — What a square number is","body":"7²: Dots in each row → 7 · How many rows? → 7 · 7 rows of 7 → 49","cta":"Watch it step by step","level":5,"route":"#/stop/square-dots"},"why-square-dots-why2":{"id":"why-square-dots-why2","kind":"why","src":"stop:square-dots#why2","title":"Why “What a square number is” works","body":"The little 2 means \"two of them multiplied\": 7² is 7 × 7, not 7 × 2. Knowing the squares up to 20 by heart is worth it — every trick in this palace starts from them.","cta":"See why","level":5,"route":"#/stop/square-dots"},"moment-square-dots-beat3":{"id":"moment-square-dots-beat3","kind":"moment","src":"story:square-dots#beat3","badge":{"id":"story","label":"A story"},"title":"The parade ground — on the notepad","body":"Pip: Then when the band joins, 8 rows of 8 is a bigger square! 8 × 8 = 64","cta":"Read the story","level":5,"route":"#/stop/square-dots"},"try-square-dots-L5":{"id":"try-square-dots-L5","kind":"try","level":5,"src":"try:square-dots@5/1#0","title":"What a square number is — your turn","route":"#/stop/square-dots","cta":"Practise this stop","play":{"q":"2² = ?","opts":["4","2","5"],"after":"n² means n rows of n. Lay them out and they make a perfect square."}},"trick-powers-index-idea":{"id":"trick-powers-index-idea","kind":"trick","src":"stop:powers-index#idea","title":"Powers: the little number","body":"The little raised number (the index) says how many of the big number to multiply together. 2⁵ means 2 × 2 × 2 × 2 × 2. Squared was the index 2; cubed is the index 3; the index can be anything. Work along: 2, 4, 8, 16, 32.","cta":"Learn the trick","level":5,"route":"#/stop/powers-index"},"story-powers-index-open":{"id":"story-powers-index-open","kind":"story","src":"story:powers-index#open","badge":{"id":"story","label":"A story"},"title":"The doubling rice","body":"Pip finds an old board game in the palace attic. Put 1 grain on the first square, then double it on each square after. — with Vesper and Pip.","art":"art/s-room.webp","cta":"Read the story","level":5,"route":"#/stop/powers-index"},"hook-powers-index-hook":{"id":"hook-powers-index-hook","kind":"hook","src":"stop:powers-index#hook","title":"Can you? — Powers: the little number","body":"2⁵ — five twos, multiplied.","cta":"Find out how","level":5,"route":"#/stop/powers-index"},"idea-powers-index-case0":{"id":"idea-powers-index-case0","kind":"idea","src":"stop:powers-index#case0","title":"Powers: the little number: Multiply along","body":"A small index: just keep multiplying by the big number, one step for each.","cta":"See it worked","level":5,"route":"#/stop/powers-index"},"worked-powers-index-worked0":{"id":"worked-powers-index-worked0","kind":"worked","src":"stop:powers-index#worked0","title":"Worked out — Powers: the little number: Multiply along","body":"2⁵: How many 2s are multiplied? → 5 · 2 × 2 → 4 · 4 × 2 → 8 · 8 × 2 → 16 · 16 × 2 → 32","cta":"Watch it step by step","level":5,"route":"#/stop/powers-index"},"idea-powers-index-case1":{"id":"idea-powers-index-case1","kind":"idea","src":"stop:powers-index#case1","title":"Powers: the little number: A big index: halve it","body":"Too many to multiply one by one. Work out half the power, then multiply it by itself (and by one more if the index is odd).","cta":"See it worked","level":5,"route":"#/stop/powers-index"},"worked-powers-index-worked1":{"id":"worked-powers-index-worked1","kind":"worked","src":"stop:powers-index#worked1","title":"Worked out — Powers: the little number: A big index: halve it","body":"3⁷: How many 3s are multiplied? → 7 · Half the index: 3³ → 27 · 27 × 27 → 729 · One more × 3 → 2187","cta":"Watch it step by step","level":5,"route":"#/stop/powers-index"},"idea-powers-index-case2":{"id":"idea-powers-index-case2","kind":"idea","src":"stop:powers-index#case2","title":"Powers: the little number: Doubling from 1","body":"Doubling again and again is a power of 2 in words: double 8 times is 2 to the power 8.","cta":"See it worked","level":5,"route":"#/stop/powers-index"},"worked-powers-index-worked2":{"id":"worked-powers-index-worked2","kind":"worked","src":"stop:powers-index#worked2","title":"Worked out — Powers: the little number: Doubling from 1","body":"Start at 1 and double 8 times: How many 2s are multiplied? → 8 · Half the index: 2⁴ → 16 · 16 × 16 → 256","cta":"Watch it step by step","level":5,"route":"#/stop/powers-index"},"why-powers-index-why1":{"id":"why-powers-index-why1","kind":"why","src":"stop:powers-index#why1","title":"Why “Powers: the little number” works","body":"Powers grow astonishingly fast, because each step multiplies what you already have. A pond weed that doubles every day covers 2 patches on day one, then 4, 8, 16… after only 20 doublings it is over a million. That is called exponential growth.","cta":"See why","level":5,"route":"#/stop/powers-index"},"why-powers-index-why2":{"id":"why-powers-index-why2","kind":"why","src":"stop:powers-index#why2","title":"Why “Powers: the little number” works","body":"For a big index, split it in half: 2¹⁰ is 2⁵ × 2⁵ = 32 × 32 = 1024. Two halves of the same power multiplied together make the whole power.","cta":"See why","level":5,"route":"#/stop/powers-index"},"algebra-powers-index-alg":{"id":"algebra-powers-index-alg","kind":"algebra","src":"stop:powers-index#alg","title":"The algebra behind “Powers: the little number”","body":"aⁿ = a × a × … × a  (n of them)   ·   a²ᵏ = aᵏ × aᵏ","cta":"See why","level":5,"route":"#/stop/powers-index"},"moment-powers-index-beat4":{"id":"moment-powers-index-beat4","kind":"moment","src":"story:powers-index#beat4","badge":{"id":"story","label":"A story"},"title":"The doubling rice — on the notepad","body":"Vesper: No. Two lots of five doublings, one after the other. 32 × 32 = 1024","cta":"Read the story","level":5,"route":"#/stop/powers-index"},"moral-powers-index-beat5":{"id":"moral-powers-index-beat5","kind":"moral","src":"story:powers-index#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The doubling rice”","body":"Over a thousand! The little number, the power, says how many twos. 2 to the power 5 is thirty-two.","cta":"Read the story","level":5,"route":"#/stop/powers-index"},"try-powers-index-L5":{"id":"try-powers-index-L5","kind":"try","level":5,"src":"try:powers-index@5/1#0","title":"Powers: the little number — your turn","route":"#/stop/powers-index","cta":"Practise this stop","play":{"q":"10³ = ?","opts":["1000","3","100"],"after":"The little raised number (the index) says how many of the big number to multiply together."}},"trick-add-decimals-idea":{"id":"trick-add-decimals-idea","kind":"trick","src":"stop:add-decimals#idea","title":"Line up the point","body":"Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers. You can only add things of the same kind: ones to ones, tenths to tenths. Writing 3.5 and 1.27 with their points in a column puts every digit under a digit of the same value.","cta":"Learn the trick","level":5,"route":"#/stop/add-decimals"},"story-add-decimals-open":{"id":"story-add-decimals-open","kind":"story","src":"story:add-decimals#open","badge":{"id":"story","label":"A story"},"title":"Two bags of shopping","body":"Nova buys bread for 3.5 coins and cheese for 1.27 coins. — with Theo and Nova.","art":"art/s-shop.webp","cta":"Read the story","level":5,"route":"#/stop/add-decimals"},"hook-add-decimals-hook":{"id":"hook-add-decimals-hook","kind":"hook","src":"stop:add-decimals#hook","title":"Can you? — Line up the point","body":"3.5 + 1.27 — why is it not 1.62?","cta":"Find out how","level":5,"route":"#/stop/add-decimals"},"idea-add-decimals-case0":{"id":"idea-add-decimals-case0","kind":"idea","src":"stop:add-decimals#case0","title":"Line up the point: Add, same places","body":"Both have tenths only, so the points already line up. Add the tenths as whole numbers, then put the point back.","cta":"See it worked","level":5,"route":"#/stop/add-decimals"},"worked-add-decimals-worked0":{"id":"worked-add-decimals-worked0","kind":"worked","src":"stop:add-decimals#worked0","title":"Worked out — Line up the point: Add, same places","body":"2.4 + 1.8: 2.4 in tenths → 24 · 1.8 in tenths → 18 · Add the tenths → 42 · Back to a decimal: ÷ 10 → 4.2","cta":"Watch it step by step","level":5,"route":"#/stop/add-decimals"},"idea-add-decimals-case1":{"id":"idea-add-decimals-case1","kind":"idea","src":"stop:add-decimals#case1","title":"Line up the point: Add, different places","body":"One number has hundredths and the other does not. Turn both into hundredths first, so tenths add to tenths.","cta":"See it worked","level":5,"route":"#/stop/add-decimals"},"worked-add-decimals-worked1":{"id":"worked-add-decimals-worked1","kind":"worked","src":"stop:add-decimals#worked1","title":"Worked out — Line up the point: Add, different places","body":"3.5 + 1.27: 3.5 in hundredths → 350 · 1.27 in hundredths → 127 · Add the hundredths → 477 · Back to a decimal: ÷ 100 → 4.77","cta":"Watch it step by step","level":5,"route":"#/stop/add-decimals"},"idea-add-decimals-case2":{"id":"idea-add-decimals-case2","kind":"idea","src":"stop:add-decimals#case2","title":"Line up the point: Take away, same places","body":"Line up the points and take tenths from tenths, just like whole numbers.","cta":"See it worked","level":5,"route":"#/stop/add-decimals"},"worked-add-decimals-worked2":{"id":"worked-add-decimals-worked2","kind":"worked","src":"stop:add-decimals#worked2","title":"Worked out — Line up the point: Take away, same places","body":"5.2 − 3.7: 5.2 in tenths → 52 · 3.7 in tenths → 37 · Take away the tenths → 15 · Back to a decimal: ÷ 10 → 1.5","cta":"Watch it step by step","level":5,"route":"#/stop/add-decimals"},"idea-add-decimals-case3":{"id":"idea-add-decimals-case3","kind":"idea","src":"stop:add-decimals#case3","title":"Line up the point: Take away, different places","body":"The shorter number gets a zero in its empty place — 5.2 is 520 hundredths — then take away as whole numbers.","cta":"See it worked","level":5,"route":"#/stop/add-decimals"},"worked-add-decimals-worked3":{"id":"worked-add-decimals-worked3","kind":"worked","src":"stop:add-decimals#worked3","title":"Worked out — Line up the point: Take away, different places","body":"5.2 − 1.45: 5.2 in hundredths → 520 · 1.45 in hundredths → 145 · Take away the hundredths → 375 · Back to a decimal: ÷ 100 → 3.75","cta":"Watch it step by step","level":5,"route":"#/stop/add-decimals"},"why-add-decimals-why1":{"id":"why-add-decimals-why1","kind":"why","src":"stop:add-decimals#why1","title":"Why “Line up the point” works","body":"The 5 in 3.5 is 5 tenths, which is 50 hundredths. So 3.5 is 350 hundredths and 1.27 is 127 hundredths. Now it is a sum of whole numbers: 477 hundredths, which is 4.77. Taking away works the same way: 5.2 − 1.45 is 520 − 145 = 375 hundredths, 3.75. The empty place in 5.2 is a zero, not a gap to skip.","cta":"See why","level":5,"route":"#/stop/add-decimals"},"why-add-decimals-why2":{"id":"why-add-decimals-why2","kind":"why","src":"stop:add-decimals#why2","title":"Why “Line up the point” works","body":"Adding 5 and 27 as if they were the same kind of thing (to get 1.62) is adding tenths to hundredths — like adding 5 metres to 27 centimetres and calling it 32. Lining up the point is what stops it.","cta":"See why","level":5,"route":"#/stop/add-decimals"},"algebra-add-decimals-alg":{"id":"algebra-add-decimals-alg","kind":"algebra","src":"stop:add-decimals#alg","title":"The algebra behind “Line up the point”","body":"a + b = (a × 10ᵈ + b × 10ᵈ) ÷ 10ᵈ, d = the most decimal places","cta":"See why","level":5,"route":"#/stop/add-decimals"},"moment-add-decimals-beat4":{"id":"moment-add-decimals-beat4","kind":"moment","src":"story:add-decimals#beat4","badge":{"id":"story","label":"A story"},"title":"Two bags of shopping — on the notepad","body":"Nova: 477 hundredths. Back to coins… 477 ÷ 100 = 4.77","cta":"Read the story","level":5,"route":"#/stop/add-decimals"},"moral-add-decimals-beat5":{"id":"moral-add-decimals-beat5","kind":"moral","src":"story:add-decimals#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “Two bags of shopping”","body":"4.77 coins. Tenths under tenths, every time.","cta":"Read the story","level":5,"route":"#/stop/add-decimals"},"try-add-decimals-L5":{"id":"try-add-decimals-L5","kind":"try","level":5,"src":"try:add-decimals@5/1#0","title":"Line up the point — your turn","route":"#/stop/add-decimals","cta":"Practise this stop","play":{"q":"4.5 + 8.8 = ?","opts":["13.3","45","88"],"after":"Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers."}},"trick-round-decimals-idea":{"id":"trick-round-decimals-idea","kind":"trick","src":"stop:round-decimals#idea","title":"Rounding decimals","body":"Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up. Rounding asks which of two neighbours a number is nearer. To one decimal place, 12.68 sits between 12.6 and 12.7 on the number line.","cta":"Learn the trick","level":5,"route":"#/stop/round-decimals"},"story-round-decimals-open":{"id":"story-round-decimals-open","kind":"story","src":"story:round-decimals#open","badge":{"id":"story","label":"A story"},"title":"The longest fish","body":"On the beach, Dax measures a piece of driftwood: 12.68 metres of rope would go round it. — with Suki and Dax.","art":"art/s-beach.webp","cta":"Read the story","level":5,"route":"#/stop/round-decimals"},"hook-round-decimals-hook":{"id":"hook-round-decimals-hook","kind":"hook","src":"stop:round-decimals#hook","title":"Can you? — Rounding decimals","body":"12.68 m of rope — about how much, to one decimal place?","cta":"Find out how","level":5,"route":"#/stop/round-decimals"},"idea-round-decimals-case0":{"id":"idea-round-decimals-case0","kind":"idea","src":"stop:round-decimals#case0","title":"Rounding decimals: To a whole number: stay","body":"Cut it off after the ones. The next digit is under 5, so the number is in the first half of the gap — it stays.","cta":"See it worked","level":5,"route":"#/stop/round-decimals"},"worked-round-decimals-worked0":{"id":"worked-round-decimals-worked0","kind":"worked","src":"stop:round-decimals#worked0","title":"Worked out — Rounding decimals: To a whole number: stay","body":"Round 7.3 to the nearest whole number: Cut it off after the ones → 7 · The very next digit → 3 · 5 or more goes up; 4 or less stays → 7","cta":"Watch it step by step","level":5,"route":"#/stop/round-decimals"},"idea-round-decimals-case1":{"id":"idea-round-decimals-case1","kind":"idea","src":"stop:round-decimals#case1","title":"Rounding decimals: To a whole number: up","body":"The next digit is 5 — exactly halfway — and halfway always rounds up.","cta":"See it worked","level":5,"route":"#/stop/round-decimals"},"idea-round-decimals-case2":{"id":"idea-round-decimals-case2","kind":"idea","src":"stop:round-decimals#case2","title":"Rounding decimals: To decimal places: up","body":"Cut it off after the places you want. An 8 next means you are most of the way to the next one up.","cta":"See it worked","level":5,"route":"#/stop/round-decimals"},"worked-round-decimals-worked2":{"id":"worked-round-decimals-worked2","kind":"worked","src":"stop:round-decimals#worked2","title":"Worked out — Rounding decimals: To decimal places: up","body":"Round 12.68 to 1 decimal place: Cut it off after 1 decimal place → 12.6 · The very next digit → 8 · 5 or more goes up; 4 or less stays → 12.7","cta":"Watch it step by step","level":5,"route":"#/stop/round-decimals"},"idea-round-decimals-case3":{"id":"idea-round-decimals-case3","kind":"idea","src":"stop:round-decimals#case3","title":"Rounding decimals: To decimal places: stay","body":"The next digit is under 5, so you stay — and the digits after it cannot pull you over halfway.","cta":"See it worked","level":5,"route":"#/stop/round-decimals"},"worked-round-decimals-worked3":{"id":"worked-round-decimals-worked3","kind":"worked","src":"stop:round-decimals#worked3","title":"Worked out — Rounding decimals: To decimal places: stay","body":"Round 4.329 to 1 decimal place: Cut it off after 1 decimal place → 4.3 · The very next digit → 2 · 5 or more goes up; 4 or less stays → 4.3","cta":"Watch it step by step","level":5,"route":"#/stop/round-decimals"},"why-round-decimals-why1":{"id":"why-round-decimals-why1","kind":"why","src":"stop:round-decimals#why1","title":"Why “Rounding decimals” works","body":"The digit just after where you stop tells you how far along the gap you are. An 8 means eight tenths of the way from 12.6 to 12.7 — much nearer 12.7. A digit under 5 means you are in the first half, so you stay.","cta":"See why","level":5,"route":"#/stop/round-decimals"},"why-round-decimals-why2":{"id":"why-round-decimals-why2","kind":"why","src":"stop:round-decimals#why2","title":"Why “Rounding decimals” works","body":"Exactly 5 is exactly halfway, and the rule everyone agrees on is to round it up — so a number never has to argue about which side it belongs to. Only the one next digit counts; the digits after it cannot pull you back over halfway.","cta":"See why","level":5,"route":"#/stop/round-decimals"},"algebra-round-decimals-alg":{"id":"algebra-round-decimals-alg","kind":"algebra","src":"stop:round-decimals#alg","title":"The algebra behind “Rounding decimals”","body":"round x to d places: look at digit d + 1; ≥ 5 → up, < 5 → stay","cta":"See why","level":5,"route":"#/stop/round-decimals"},"moment-round-decimals-beat4":{"id":"moment-round-decimals-beat4","kind":"moment","src":"story:round-decimals#beat4","badge":{"id":"story","label":"A story"},"title":"The longest fish — on the notepad","body":"Dax: Five or more goes up. So about 12.7 metres. 12.6 + 0.1 = 12.7","cta":"Read the story","level":5,"route":"#/stop/round-decimals"},"moral-round-decimals-beat5":{"id":"moral-round-decimals-beat5","kind":"moral","src":"story:round-decimals#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “The longest fish”","body":"And to the nearest whole metre, the 6 decides: 13.","cta":"Read the story","level":5,"route":"#/stop/round-decimals"},"try-round-decimals-L5":{"id":"try-round-decimals-L5","kind":"try","level":5,"src":"try:round-decimals@5/1#0","title":"Rounding decimals — your turn","route":"#/stop/round-decimals","cta":"Practise this stop","play":{"q":"Round 13.5 to the nearest whole number = ?","opts":["14","13","5"],"after":"Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up."}},"trick-fraction-decimal-percent-idea":{"id":"trick-fraction-decimal-percent-idea","kind":"trick","src":"stop:fraction-decimal-percent#idea","title":"Fractions, decimals, per cents","body":"Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths. Per cent means \"out of a hundred\" (cent is the old word for hundred, as in century). So 75% is just another way to write 75/100.","cta":"Learn the trick","level":5,"route":"#/stop/fraction-decimal-percent"},"story-fraction-decimal-percent-open":{"id":"story-fraction-decimal-percent-open","kind":"story","src":"story:fraction-decimal-percent#open","badge":{"id":"story","label":"A story"},"title":"Three signs, one discount","body":"Three shops on the high street. One sign says 3/4 of the price. One says 0.75 of the price. One says 75%. — with Ines and Pip.","art":"art/s-shop.webp","cta":"Read the story","level":5,"route":"#/stop/fraction-decimal-percent"},"hook-fraction-decimal-percent-hook":{"id":"hook-fraction-decimal-percent-hook","kind":"hook","src":"stop:fraction-decimal-percent#hook","title":"Can you? — Fractions, decimals, per cents","body":"3/4, 0.75 and 75% — are those three different numbers?","cta":"Find out how","level":5,"route":"#/stop/fraction-decimal-percent"},"idea-fraction-decimal-percent-case0":{"id":"idea-fraction-decimal-percent-case0","kind":"idea","src":"stop:fraction-decimal-percent#case0","title":"Fractions, decimals, per cents: Fraction to decimal","body":"Make the bottom 100 with an equivalent fraction. The hundredths are the two places after the point.","cta":"See it worked","level":5,"route":"#/stop/fraction-decimal-percent"},"worked-fraction-decimal-percent-worked0":{"id":"worked-fraction-decimal-percent-worked0","kind":"worked","src":"stop:fraction-decimal-percent#worked0","title":"Worked out — Fractions, decimals, per cents: Fraction to decimal","body":"3/4 as a decimal: 3/4 = ?/100 → 75 · hundredths as a decimal → 0.75","cta":"Watch it step by step","level":5,"route":"#/stop/fraction-decimal-percent"},"idea-fraction-decimal-percent-case1":{"id":"idea-fraction-decimal-percent-case1","kind":"idea","src":"stop:fraction-decimal-percent#case1","title":"Fractions, decimals, per cents: Decimal to percentage","body":"Read the decimal as hundredths — and per cent means hundredths, so that is the percentage.","cta":"See it worked","level":5,"route":"#/stop/fraction-decimal-percent"},"worked-fraction-decimal-percent-worked1":{"id":"worked-fraction-decimal-percent-worked1","kind":"worked","src":"stop:fraction-decimal-percent#worked1","title":"Worked out — Fractions, decimals, per cents: Decimal to percentage","body":"0.36 as a percentage: 0.36 is how many hundredths? → 36 · Per cent means hundredths → 36","cta":"Watch it step by step","level":5,"route":"#/stop/fraction-decimal-percent"},"idea-fraction-decimal-percent-case2":{"id":"idea-fraction-decimal-percent-case2","kind":"idea","src":"stop:fraction-decimal-percent#case2","title":"Fractions, decimals, per cents: Percentage to fraction","body":"Write it over 100, then simplify by dividing top and bottom by the same number.","cta":"See it worked","level":5,"route":"#/stop/fraction-decimal-percent"},"worked-fraction-decimal-percent-worked2":{"id":"worked-fraction-decimal-percent-worked2","kind":"worked","src":"stop:fraction-decimal-percent#worked2","title":"Worked out — Fractions, decimals, per cents: Percentage to fraction","body":"35% as a fraction: 35% = ?/100 → 35 · Divide top and bottom by → 5 · The fraction → 7/20","cta":"Watch it step by step","level":5,"route":"#/stop/fraction-decimal-percent"},"idea-fraction-decimal-percent-case3":{"id":"idea-fraction-decimal-percent-case3","kind":"idea","src":"stop:fraction-decimal-percent#case3","title":"Fractions, decimals, per cents: Fraction to percentage","body":"Make the bottom 100, and the top IS the percentage.","cta":"See it worked","level":5,"route":"#/stop/fraction-decimal-percent"},"worked-fraction-decimal-percent-worked3":{"id":"worked-fraction-decimal-percent-worked3","kind":"worked","src":"stop:fraction-decimal-percent#worked3","title":"Worked out — Fractions, decimals, per cents: Fraction to percentage","body":"2/5 as a percentage: 2/5 = ?/100 → 40 · Hundredths are per cent → 40","cta":"Watch it step by step","level":5,"route":"#/stop/fraction-decimal-percent"},"idea-fraction-decimal-percent-case4":{"id":"idea-fraction-decimal-percent-case4","kind":"idea","src":"stop:fraction-decimal-percent#case4","title":"Fractions, decimals, per cents: Decimal via thousandths","body":"Eighths do not go into 100, but they do go into 1000. Thousandths are three places after the point.","cta":"See it worked","level":5,"route":"#/stop/fraction-decimal-percent"},"worked-fraction-decimal-percent-worked4":{"id":"worked-fraction-decimal-percent-worked4","kind":"worked","src":"stop:fraction-decimal-percent#worked4","title":"Worked out — Fractions, decimals, per cents: Decimal via thousandths","body":"3/8 as a decimal: 3/8 = ?/1000 → 375 · thousandths as a decimal → 0.375","cta":"Watch it step by step","level":5,"route":"#/stop/fraction-decimal-percent"},"idea-fraction-decimal-percent-case5":{"id":"idea-fraction-decimal-percent-case5","kind":"idea","src":"stop:fraction-decimal-percent#case5","title":"Fractions, decimals, per cents: Percentage via thousandths","body":"Make the bottom 1000, then divide by 10 to get hundredths — per cent can have a decimal too.","cta":"See it worked","level":5,"route":"#/stop/fraction-decimal-percent"},"worked-fraction-decimal-percent-worked5":{"id":"worked-fraction-decimal-percent-worked5","kind":"worked","src":"stop:fraction-decimal-percent#worked5","title":"Worked out — Fractions, decimals, per cents: Percentage via thousandths","body":"3/8 as a percentage: 3/8 = ?/1000 → 375 · ÷ 10 for per cent → 37.5","cta":"Watch it step by step","level":5,"route":"#/stop/fraction-decimal-percent"},"why-fraction-decimal-percent-why1":{"id":"why-fraction-decimal-percent-why1","kind":"why","src":"stop:fraction-decimal-percent#why1","title":"Why “Fractions, decimals, per cents” works","body":"And 75 hundredths as a decimal is 0.75 — the second place after the point is the hundredths place. So all three are one number wearing different clothes: 3/4 = 75/100 = 0.75 = 75%.","cta":"See why","level":5,"route":"#/stop/fraction-decimal-percent"},"why-fraction-decimal-percent-why2":{"id":"why-fraction-decimal-percent-why2","kind":"why","src":"stop:fraction-decimal-percent#why2","title":"Why “Fractions, decimals, per cents” works","body":"To get from a fraction to hundredths, use equivalent fractions: 3/4 = 75/100 because 4 × 25 = 100, so 3 × 25 = 75. Some fractions need thousandths instead: 3/8 = 375/1000 = 0.375.","cta":"See why","level":5,"route":"#/stop/fraction-decimal-percent"},"algebra-fraction-decimal-percent-alg":{"id":"algebra-fraction-decimal-percent-alg","kind":"algebra","src":"stop:fraction-decimal-percent#alg","title":"The algebra behind “Fractions, decimals, per cents”","body":"a/b = (a × 100/b)/100 = (a × 100/b)% ","cta":"See why","level":5,"route":"#/stop/fraction-decimal-percent"},"moment-fraction-decimal-percent-beat3":{"id":"moment-fraction-decimal-percent-beat3","kind":"moment","src":"story:fraction-decimal-percent#beat3","badge":{"id":"story","label":"A story"},"title":"Three signs, one discount — on the notepad","body":"Ines: …so 3 quarters is 75 hundredths. 3 × 25 = 75","cta":"Read the story","level":5,"route":"#/stop/fraction-decimal-percent"},"moral-fraction-decimal-percent-beat5":{"id":"moral-fraction-decimal-percent-beat5","kind":"moral","src":"story:fraction-decimal-percent#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “Three signs, one discount”","body":"Three signs, one number. Pick the shop with the nicest cake.","cta":"Read the story","level":5,"route":"#/stop/fraction-decimal-percent"},"try-fraction-decimal-percent-L5":{"id":"try-fraction-decimal-percent-L5","kind":"try","level":5,"src":"try:fraction-decimal-percent@5/1#0","title":"Fractions, decimals, per cents — your turn","route":"#/stop/fraction-decimal-percent","cta":"Practise this stop","play":{"q":"3/10 as a decimal = ?","opts":["0.3","30","0.4"],"after":"Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths."}},"trick-percent-of-amount-idea":{"id":"trick-percent-of-amount-idea","kind":"trick","src":"stop:percent-of-amount#idea","title":"Percentages of an amount","body":"Find 10% by dividing by 10. Build everything else from 10% and its half, 5%. 10% means 10 out of every 100 — one tenth. So 10% of anything is that thing divided by 10: 10% of 60 is 6.","cta":"Learn the trick","level":5,"route":"#/stop/percent-of-amount"},"story-percent-of-amount-open":{"id":"story-percent-of-amount-open","kind":"story","src":"story:percent-of-amount#open","badge":{"id":"story","label":"A story"},"title":"The harbour tax","body":"The fishing boat brought in 60 kg of fish. 35% goes to the market in town. — with Ines and Rafi.","art":"art/s-harbour.webp","cta":"Read the story","level":5,"route":"#/stop/percent-of-amount"},"idea-percent-of-amount-case0":{"id":"idea-percent-of-amount-case0","kind":"idea","src":"stop:percent-of-amount#case0","title":"Percentages of an amount: Just 10%","body":"10% is one tenth, so divide by 10. Every other percentage here is built from this one.","cta":"See it worked","level":5,"route":"#/stop/percent-of-amount"},"idea-percent-of-amount-case1":{"id":"idea-percent-of-amount-case1","kind":"idea","src":"stop:percent-of-amount#case1","title":"Percentages of an amount: Lots of 10%","body":"30% is three lots of 10%: find 10% first, then multiply by how many tens.","cta":"See it worked","level":5,"route":"#/stop/percent-of-amount"},"idea-percent-of-amount-case2":{"id":"idea-percent-of-amount-case2","kind":"idea","src":"stop:percent-of-amount#case2","title":"Percentages of an amount: Just 5%","body":"5% is half of 10%, so find 10% and halve it.","cta":"See it worked","level":5,"route":"#/stop/percent-of-amount"},"idea-percent-of-amount-case3":{"id":"idea-percent-of-amount-case3","kind":"idea","src":"stop:percent-of-amount#case3","title":"Percentages of an amount: Tens and a 5","body":"Split it into tens and a five: 35% is 30% and 5%. Find both, then add.","cta":"See it worked","level":5,"route":"#/stop/percent-of-amount"},"why-percent-of-amount-why1":{"id":"why-percent-of-amount-why1","kind":"why","src":"stop:percent-of-amount#why1","title":"Why “Percentages of an amount” works","body":"Other percentages are made of tens. 30% is three lots of 10%: 18. And 5% is half of 10%: 3. So 35% of 60 is 18 + 3 = 21.","cta":"See why","level":5,"route":"#/stop/percent-of-amount"},"algebra-percent-of-amount-alg":{"id":"algebra-percent-of-amount-alg","kind":"algebra","src":"stop:percent-of-amount#alg","title":"The algebra behind “Percentages of an amount”","body":"p% of n = (n ÷ 10) × (p ÷ 10)","cta":"See why","level":5,"route":"#/stop/percent-of-amount"},"moral-percent-of-amount-beat5":{"id":"moral-percent-of-amount-beat5","kind":"moral","src":"story:percent-of-amount#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The harbour tax”","body":"Add them up: 21 kg to the market.","cta":"Read the story","level":5,"route":"#/stop/percent-of-amount"},"try-percent-of-amount-L5":{"id":"try-percent-of-amount-L5","kind":"try","level":5,"src":"try:percent-of-amount@5/1#0","title":"Percentages of an amount — your turn","route":"#/stop/percent-of-amount","cta":"Practise this stop","play":{"q":"10% of 280 = ?","opts":["28","10","29"],"after":"Find 10% by dividing by 10. Build everything else from 10% and its half, 5%."}},"trick-mean-fair-share-idea":{"id":"trick-mean-fair-share-idea","kind":"trick","src":"stop:mean-fair-share#idea","title":"The mean: fair shares","body":"Add everything up, then share it out equally: divide by how many numbers there are. Imagine every friend tips their tickets into one pile. Nothing is lost — the pile holds all 24. Now deal the pile out again, one each, round and round, until it is gone. Everyone ends up with the same: 6. That fair share is the mean.","cta":"Learn the trick","level":5,"route":"#/stop/mean-fair-share"},"story-mean-fair-share-open":{"id":"story-mean-fair-share-open","kind":"story","src":"story:mean-fair-share#open","badge":{"id":"story","label":"A story"},"title":"Sharing the tickets","body":"Four friends play the games. Nova wins 3 tickets, Rafi 7, Pip 5 and Suki 9. They agree to share them fairly. — with Nova and Rafi.","art":"art/s-carnival.webp","cta":"Read the story","level":5,"route":"#/stop/mean-fair-share"},"worked-mean-fair-share-worked0":{"id":"worked-mean-fair-share-worked0","kind":"worked","src":"stop:mean-fair-share#worked0","title":"Worked out — The mean: fair shares","body":"The mean of 3, 7, 5, 9: Add them all up → 24 · How many numbers? → 4 · 24 ÷ 4 → 6","cta":"Watch it step by step","level":5,"route":"#/stop/mean-fair-share"},"why-mean-fair-share-why2":{"id":"why-mean-fair-share-why2","kind":"why","src":"stop:mean-fair-share#why2","title":"Why “The mean: fair shares” works","body":"That is why the mean needs both steps. Adding makes the pile; dividing by how many people deals it out. Divide by the wrong number and somebody gets cheated.","cta":"See why","level":5,"route":"#/stop/mean-fair-share"},"moment-mean-fair-share-beat2":{"id":"moment-mean-fair-share-beat2","kind":"moment","src":"story:mean-fair-share#beat2","badge":{"id":"story","label":"A story"},"title":"Sharing the tickets — on the notepad","body":"Nova: Now deal them out, one each, round and round, between the four of us. 24 ÷ 4 = 6","cta":"Read the story","level":5,"route":"#/stop/mean-fair-share"},"try-mean-fair-share-L5":{"id":"try-mean-fair-share-L5","kind":"try","level":5,"src":"try:mean-fair-share@5/1#0","title":"The mean: fair shares — your turn","route":"#/stop/mean-fair-share","cta":"Practise this stop","play":{"q":"The mean of 6, 10, 2 = ?","opts":["6","18","3"],"after":"Add everything up, then share it out equally: divide by how many numbers there are."}},"trick-data-range-idea":{"id":"trick-data-range-idea","kind":"trick","src":"stop:data-range#idea","title":"The range: how spread out?","body":"Find the largest and the smallest, and take one from the other. Two teams can have the same mean and still be very different: one where everyone scores about 20, and one where some score 2 and some score 40. The range tells them apart.","cta":"Learn the trick","level":5,"route":"#/stop/data-range"},"story-data-range-open":{"id":"story-data-range-open","kind":"story","src":"story:data-range#open","badge":{"id":"story","label":"A story"},"title":"Two cricket teams","body":"The Reds scored 14, 31, 25, 9 and 27 runs. Pip wants to know how spread out the scores are. — with Kwame and Pip.","art":"art/s-cricket.webp","cta":"Read the story","level":5,"route":"#/stop/data-range"},"worked-data-range-worked0":{"id":"worked-data-range-worked0","kind":"worked","src":"stop:data-range#worked0","title":"Worked out — The range: how spread out?","body":"The range of 14, 31, 25, 9, 27: The largest → 31 · The smallest → 9 · 31 − 9 → 22","cta":"Watch it step by step","level":5,"route":"#/stop/data-range"},"why-data-range-why2":{"id":"why-data-range-why2","kind":"why","src":"stop:data-range#why2","title":"Why “The range: how spread out?” works","body":"Only the two ends matter. Every other number sits somewhere in between, so it cannot make the spread any wider.","cta":"See why","level":5,"route":"#/stop/data-range"},"moment-data-range-beat3":{"id":"moment-data-range-beat3","kind":"moment","src":"story:data-range#beat3","badge":{"id":"story","label":"A story"},"title":"Two cricket teams — on the notepad","body":"Kwame: The range is the distance between them. 31 − 9 = 22","cta":"Read the story","level":5,"route":"#/stop/data-range"},"try-data-range-L5":{"id":"try-data-range-L5","kind":"try","level":5,"src":"try:data-range@5/1#0","title":"The range: how spread out? — your turn","route":"#/stop/data-range","cta":"Practise this stop","play":{"q":"The range of 4, 10, 5, 5 = ?","opts":["6","10","4"],"after":"Find the largest and the smallest, and take one from the other."}},"trick-think-of-a-number-idea":{"id":"trick-think-of-a-number-idea","kind":"trick","src":"stop:think-of-a-number#idea","title":"Working backwards","body":"Start at the end and undo each step, last one first: undo + with −, and × with ÷. Think of the number going through a machine: first × 3, then + 4, and out comes 19. To get back, walk the path the other way — the last thing done is the first thing undone.","cta":"Learn the trick","level":5,"route":"#/stop/think-of-a-number"},"story-think-of-a-number-open":{"id":"story-think-of-a-number-open","kind":"story","src":"story:think-of-a-number#open","badge":{"id":"story","label":"A story"},"title":"The mind-reader","body":"A sign on the tent says \"The Mind-Reader\". Pip thinks of a number, times it by 3, adds 4, and says: \"19\". — with Vesper and Pip.","art":"art/s-carnival.webp","cta":"Read the story","level":5,"route":"#/stop/think-of-a-number"},"worked-think-of-a-number-worked0":{"id":"worked-think-of-a-number-worked0","kind":"worked","src":"stop:think-of-a-number#worked0","title":"Worked out — Working backwards","body":"? → × 3 → + 4 → 19. What number went in?: Undo + 4: 19 − 4 → 15 · Undo × 3: 15 ÷ 3 → 5","cta":"Watch it step by step","level":5,"route":"#/stop/think-of-a-number"},"why-think-of-a-number-why2":{"id":"why-think-of-a-number-why2","kind":"why","src":"stop:think-of-a-number#why2","title":"Why “Working backwards” works","body":"It is like taking off your shoes before your socks: you put the socks on first, so they come off last. Check by running 5 forwards: 5 × 3 = 15, 15 + 4 = 19.","cta":"See why","level":5,"route":"#/stop/think-of-a-number"},"moment-think-of-a-number-beat3":{"id":"moment-think-of-a-number-beat3","kind":"moment","src":"story:think-of-a-number#beat3","badge":{"id":"story","label":"A story"},"title":"The mind-reader — on the notepad","body":"Vesper: Before that you timesed by 3. Undo that too. 15 ÷ 3 = 5","cta":"Read the story","level":5,"route":"#/stop/think-of-a-number"},"try-think-of-a-number-L5":{"id":"try-think-of-a-number-L5","kind":"try","level":5,"src":"try:think-of-a-number@5/1#0","title":"Working backwards — your turn","route":"#/stop/think-of-a-number","cta":"Practise this stop","play":{"q":"? → × 3 → + 7 → 28. What number went in?","opts":["7","21","8"],"after":"Start at the end and undo each step, last one first: undo + with −, and × with ÷."}},"trick-multi-step-problems-idea":{"id":"trick-multi-step-problems-idea","kind":"trick","src":"stop:multi-step-problems#idea","title":"Problems in steps","body":"Find the question inside the question: work out the part you need first, then use it. A long problem is a few short ones in a row. \"How many tokens are left?\" cannot be answered until you know how many were spent — so that is the first question, and its answer feeds the second.","cta":"Learn the trick","level":5,"route":"#/stop/multi-step-problems"},"story-multi-step-problems-open":{"id":"story-multi-step-problems-open","kind":"story","src":"story:multi-step-problems#open","badge":{"id":"story","label":"A story"},"title":"Tokens at the fair","body":"Rafi has 50 tokens. He goes on 3 rides that cost 8 tokens each. — with Ines and Rafi.","art":"art/s-market.webp","cta":"Read the story","level":5,"route":"#/stop/multi-step-problems"},"hook-multi-step-problems-hook":{"id":"hook-multi-step-problems-hook","kind":"hook","src":"stop:multi-step-problems#hook","title":"Can you? — Problems in steps","body":"50 tokens, 3 rides at 8 tokens each. What is left? Two sums hiding in one question.","cta":"Find out how","level":5,"route":"#/stop/multi-step-problems"},"idea-multi-step-problems-case0":{"id":"idea-multi-step-problems-case0","kind":"idea","src":"stop:multi-step-problems#case0","title":"Problems in steps: What is left?","body":"You cannot take away until you know what was spent — so the times sum comes first.","cta":"See it worked","level":5,"route":"#/stop/multi-step-problems"},"worked-multi-step-problems-worked0":{"id":"worked-multi-step-problems-worked0","kind":"worked","src":"stop:multi-step-problems#worked0","title":"Worked out — Problems in steps: What is left?","body":"You have 50 tokens. You go on 3 rides at 8 tokens each. How many tokens are left?: Spent on rides: 3 × 8 → 24 · 50 − 24 → 26","cta":"Watch it step by step","level":5,"route":"#/stop/multi-step-problems"},"idea-multi-step-problems-case1":{"id":"idea-multi-step-problems-case1","kind":"idea","src":"stop:multi-step-problems#case1","title":"Problems in steps: Two things bought","body":"Two different prices make two little times sums. Work each one out, then add them.","cta":"See it worked","level":5,"route":"#/stop/multi-step-problems"},"worked-multi-step-problems-worked1":{"id":"worked-multi-step-problems-worked1","kind":"worked","src":"stop:multi-step-problems#worked1","title":"Worked out — Problems in steps: Two things bought","body":"Popcorn costs 5 tokens and a drink costs 4. You buy 3 popcorn and 2 drinks. How many tokens altogether?: 3 × 5 → 15 · 2 × 4 → 8 · 15 + 8 → 23","cta":"Watch it step by step","level":5,"route":"#/stop/multi-step-problems"},"idea-multi-step-problems-case2":{"id":"idea-multi-step-problems-case2","kind":"idea","src":"stop:multi-step-problems#case2","title":"Problems in steps: Change from a payment","body":"Cost the candy floss, cost the lollies, add them — and only then take the total from what you paid.","cta":"See it worked","level":5,"route":"#/stop/multi-step-problems"},"worked-multi-step-problems-worked2":{"id":"worked-multi-step-problems-worked2","kind":"worked","src":"stop:multi-step-problems#worked2","title":"Worked out — Problems in steps: Change from a payment","body":"Candy floss costs 8 tokens and a lolly costs 5. You buy 2 candy floss and 3 lollies, and pay with 50 tokens. What is your change?: 2 × 8 → 16 · 3 × 5 → 15 · Total: 16 + 15 → 31 · 50 − 31 → 19","cta":"Watch it step by step","level":5,"route":"#/stop/multi-step-problems"},"idea-multi-step-problems-case3":{"id":"idea-multi-step-problems-case3","kind":"idea","src":"stop:multi-step-problems#case3","title":"Problems in steps: Breaks between shows","body":"There is a break between each pair of shows, not after the last — so one fewer break than shows.","cta":"See it worked","level":5,"route":"#/stop/multi-step-problems"},"worked-multi-step-problems-worked3":{"id":"worked-multi-step-problems-worked3","kind":"worked","src":"stop:multi-step-problems#worked3","title":"Worked out — Problems in steps: Breaks between shows","body":"There are 3 puppet shows in a row. Each lasts 20 minutes, with a 10-minute break between shows. How many minutes from the start of the first to the end of the last?: Show time: 3 × 20 → 60 · Breaks: there are 2, so 2 × 10 → 20 · 60 + 20 → 80","cta":"Watch it step by step","level":5,"route":"#/stop/multi-step-problems"},"idea-multi-step-problems-case4":{"id":"idea-multi-step-problems-case4","kind":"idea","src":"stop:multi-step-problems#case4","title":"Problems in steps: Turns in a queue","body":"First find how many rides it takes to fit everyone in, then times by how long each ride lasts.","cta":"See it worked","level":5,"route":"#/stop/multi-step-problems"},"worked-multi-step-problems-worked4":{"id":"worked-multi-step-problems-worked4","kind":"worked","src":"stop:multi-step-problems#worked4","title":"Worked out — Problems in steps: Turns in a queue","body":"12 children are queuing for the dodgems. 4 can ride at once, and each ride lasts 5 minutes. How many minutes until everyone has had a go?: How many rides? 12 ÷ 4 → 3 · 3 × 5 → 15","cta":"Watch it step by step","level":5,"route":"#/stop/multi-step-problems"},"idea-multi-step-problems-case5":{"id":"idea-multi-step-problems-case5","kind":"idea","src":"stop:multi-step-problems#case5","title":"Problems in steps: Pool, then share","body":"Put all the sweets in one pile first, then share the pile equally.","cta":"See it worked","level":5,"route":"#/stop/multi-step-problems"},"worked-multi-step-problems-worked5":{"id":"worked-multi-step-problems-worked5","kind":"worked","src":"stop:multi-step-problems#worked5","title":"Worked out — Problems in steps: Pool, then share","body":"4 friends buy 3 packs of sweets with 8 in each pack. They share them equally. How many does each friend get?: All the sweets: 3 × 8 → 24 · 24 ÷ 4 → 6","cta":"Watch it step by step","level":5,"route":"#/stop/multi-step-problems"},"why-multi-step-problems-why1":{"id":"why-multi-step-problems-why1","kind":"why","src":"stop:multi-step-problems#why1","title":"Why “Problems in steps” works","body":"Write each step as its own little sum. 3 rides at 8 tokens is 3 × 8 = 24 spent; 50 − 24 = 26 left. Each sum is easy; the skill is putting them in the right order. Watch the gaps, too: 3 shows in a row have only 2 breaks between them, like 3 fence posts with 2 gaps.","cta":"See why","level":5,"route":"#/stop/multi-step-problems"},"why-multi-step-problems-why2":{"id":"why-multi-step-problems-why2","kind":"why","src":"stop:multi-step-problems#why2","title":"Why “Problems in steps” works","body":"Then check the answer makes sense: you cannot have more tokens left than you started with, and a show cannot finish before it starts. A silly answer means a step was done the wrong way round.","cta":"See why","level":5,"route":"#/stop/multi-step-problems"},"algebra-multi-step-problems-alg":{"id":"algebra-multi-step-problems-alg","kind":"algebra","src":"stop:multi-step-problems#alg","title":"The algebra behind “Problems in steps”","body":"left = start − (number × price)","cta":"See why","level":5,"route":"#/stop/multi-step-problems"},"moment-multi-step-problems-beat3":{"id":"moment-multi-step-problems-beat3","kind":"moment","src":"story:multi-step-problems#beat3","badge":{"id":"story","label":"A story"},"title":"Tokens at the fair — on the notepad","body":"Rafi: Now take that from what I started with. 50 − 24 = 26","cta":"Read the story","level":5,"route":"#/stop/multi-step-problems"},"moral-multi-step-problems-beat5":{"id":"moral-multi-step-problems-beat5","kind":"moral","src":"story:multi-step-problems#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “Tokens at the fair”","body":"Twenty-six tokens left. Two little sums, in the right order.","cta":"Read the story","level":5,"route":"#/stop/multi-step-problems"},"try-multi-step-problems-L5":{"id":"try-multi-step-problems-L5","kind":"try","level":5,"src":"try:multi-step-problems@5/1#0","title":"Problems in steps — your turn","route":"#/stop/multi-step-problems","cta":"Practise this stop","play":{"q":"2 friends buy 2 packs of sweets with 8 in each pack. They share them equally. How many does each friend get?","opts":["8","16","9"],"after":"Find the question inside the question: work out the part you need first, then use it."}},"word-angles-on-a-line":{"id":"word-angles-on-a-line","kind":"word","src":"dictionary:angles on a line#def","title":"angles on a line","body":"Turns that sit side by side on one straight line; together they make 180°. For example: 70° and 110°.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-angles-on-a-line":{"id":"wordq-angles-on-a-line","kind":"wordq","src":"dictionary:angles on a line#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “70° and 110°.”","opts":["angles on a line","scale","composite number"],"after":"angles on a line: Turns that sit side by side on one straight line; together they make 180°."},"level":5},"word-angles-round-a-point":{"id":"word-angles-round-a-point","kind":"word","src":"dictionary:angles round a point#def","title":"angles round a point","body":"Turns that fill the whole way round one point; together they make 360°. For example: 90° + 120° + 150° = 360°.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-angles-round-a-point":{"id":"wordq-angles-round-a-point","kind":"wordq","src":"dictionary:angles round a point#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “90° + 120° + 150° = 360°.”","opts":["angles round a point","divisible","tenth"],"after":"angles round a point: Turns that fill the whole way round one point; together they make 360°."},"level":5},"word-average":{"id":"word-average","kind":"word","src":"dictionary:average#def","title":"average","body":"One number that stands for a whole list — the mean, the median or the mode. For example: For 4, 6, 6, 8 all three give 6.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-average":{"id":"wordq-average","kind":"wordq","src":"dictionary:average#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “For 4, 6, 6, 8 all three give 6.”","opts":["average","protractor","equivalent fractions"],"after":"average: One number that stands for a whole list — the mean, the median or the mode."},"level":5},"word-base":{"id":"word-base","kind":"word","src":"dictionary:base#def","title":"base","body":"The number being multiplied in a power (the 2 in 2⁵) — or the side a shape stands on. For example: In 10³ it is the 10; in a triangle it is the bottom side.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-base":{"id":"wordq-base","kind":"wordq","src":"dictionary:base#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “In 10³ it is the 10; in a triangle it is the bottom side.”","opts":["base","angles on a line","isosceles triangle"],"after":"base: The number being multiplied in a power (the 2 in 2⁵) — or the side a shape stands on."},"level":5},"word-bidmas":{"id":"word-bidmas","kind":"word","src":"dictionary:BIDMAS#def","title":"BIDMAS","body":"A memory word for what goes first: Brackets, Indices, Division and Multiplication, Addition and Subtraction. For example: (2 + 3)² − 4 = 25 − 4 = 21.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-bidmas":{"id":"wordq-bidmas","kind":"wordq","src":"dictionary:BIDMAS#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “(2 + 3)² − 4 = 25 − 4 = 21.”","opts":["BIDMAS","pyramid","squared"],"after":"BIDMAS: A memory word for what goes first: Brackets, Indices, Division and Multiplication, Addition and Subtraction."},"level":5},"word-brackets":{"id":"word-brackets","kind":"word","src":"dictionary:brackets#def","title":"brackets","body":"The marks ( ) that mean “work this part out first”. For example: (2 + 3) × 4 = 20.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"word-composite-number":{"id":"word-composite-number","kind":"word","src":"dictionary:composite number#def","title":"composite number","body":"A whole number with more than two factors, so it can be made by multiplying smaller whole numbers. For example: 15 = 3 × 5.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-composite-number":{"id":"wordq-composite-number","kind":"wordq","src":"dictionary:composite number#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “15 = 3 × 5.”","opts":["composite number","Vedic maths","data"],"after":"composite number: A whole number with more than two factors, so it can be made by multiplying smaller whole numbers."},"level":5},"word-compound-shape":{"id":"word-compound-shape","kind":"word","src":"dictionary:compound shape#def","title":"compound shape","body":"A shape made by joining simpler shapes together. For example: An L-shape: 6 × 2 plus 2 × 3 = 12 + 6 = 18 squares.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-compound-shape":{"id":"wordq-compound-shape","kind":"wordq","src":"dictionary:compound shape#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “An L-shape: 6 × 2 plus 2 × 3 = 12 + 6 = 18 squares.”","opts":["compound shape","simplify","subtraction"],"after":"compound shape: A shape made by joining simpler shapes together."},"level":5},"word-function-machine":{"id":"word-function-machine","kind":"word","src":"dictionary:function machine#def","title":"function machine","body":"A box that takes a number in, does something to it, and sends the result out. For example: In 5 → × 2 → + 3 → out 13.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-function-machine":{"id":"wordq-function-machine","kind":"wordq","src":"dictionary:function machine#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “In 5 → × 2 → + 3 → out 13.”","opts":["function machine","unlikely","times table"],"after":"function machine: A box that takes a number in, does something to it, and sends the result out."},"level":5},"word-index":{"id":"word-index","kind":"word","src":"dictionary:index#def","title":"index","body":"The small raised number that says how many times the base is multiplied by itself. Plural: indices. For example: In 2⁵ it is the 5: 2 × 2 × 2 × 2 × 2 = 32.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-index":{"id":"wordq-index","kind":"wordq","src":"dictionary:index#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “In 2⁵ it is the 5: 2 × 2 × 2 × 2 × 2 = 32.”","opts":["index","polygon","difference of two squares"],"after":"index: The small raised number that says how many times the base is multiplied by itself. Plural: indices."},"level":5},"word-interest":{"id":"word-interest","kind":"word","src":"dictionary:interest#def","title":"interest","body":"Extra money paid for borrowing, or earned for saving — usually a percentage each year. For example: 5% a year on £200 is £10 a year.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-interest":{"id":"wordq-interest","kind":"wordq","src":"dictionary:interest#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “5% a year on £200 is £10 a year.”","opts":["interest","double","pi"],"after":"interest: Extra money paid for borrowing, or earned for saving — usually a percentage each year."},"level":5},"word-long-multiplication":{"id":"word-long-multiplication","kind":"word","src":"dictionary:long multiplication#def","title":"long multiplication","body":"A written method: multiply by each digit of the second number in turn, then add the rows. For example: 23 × 14 = 23 × 4 + 23 × 10 = 92 + 230 = 322.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-long-multiplication":{"id":"wordq-long-multiplication","kind":"wordq","src":"dictionary:long multiplication#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “23 × 14 = 23 × 4 + 23 × 10 = 92 + 230 = 322.”","opts":["long multiplication","scalene triangle","vertex"],"after":"long multiplication: A written method: multiply by each digit of the second number in turn, then add the rows."},"level":5},"word-mean":{"id":"word-mean","kind":"word","src":"dictionary:mean#def","title":"mean","body":"The fair-share average: add up all the values, then share the total equally between them. For example: 3, 5 and 10: 18 ÷ 3 = 6.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-mean":{"id":"wordq-mean","kind":"wordq","src":"dictionary:mean#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3, 5 and 10: 18 ÷ 3 = 6.”","opts":["mean","decimal place","sample space"],"after":"mean: The fair-share average: add up all the values, then share the total equally between them."},"level":5},"word-order-of-operations":{"id":"word-order-of-operations","kind":"word","src":"dictionary:order of operations#def","title":"order of operations","body":"The agreed order for working out a calculation: brackets, then powers, then × and ÷, then + and −. For example: 2 + 3 × 4 = 14, not 20.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-order-of-operations":{"id":"wordq-order-of-operations","kind":"wordq","src":"dictionary:order of operations#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “2 + 3 × 4 = 14, not 20.”","opts":["order of operations","exterior angle","decimal"],"after":"order of operations: The agreed order for working out a calculation: brackets, then powers, then × and ÷, then + and −."},"level":5},"word-outlier":{"id":"word-outlier","kind":"word","src":"dictionary:outlier#def","title":"outlier","body":"A value far away from all the others. For example: In 5, 6, 7, 6, 42 it is the 42.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-outlier":{"id":"wordq-outlier","kind":"wordq","src":"dictionary:outlier#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “In 5, 6, 7, 6, 42 it is the 42.”","opts":["outlier","Roman numerals","cubic centimetre"],"after":"outlier: A value far away from all the others."},"level":5},"word-per-cent":{"id":"word-per-cent","kind":"word","src":"dictionary:per cent#def","title":"per cent","body":"Out of every hundred. Sign: %. For example: 25% means 25 out of every 100 — the same as 1/4.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"word-percentage":{"id":"word-percentage","kind":"word","src":"dictionary:percentage#def","title":"percentage","body":"An amount written as a number out of 100. For example: 17 children out of 100 is 17%.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-percentage":{"id":"wordq-percentage","kind":"wordq","src":"dictionary:percentage#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “17 children out of 100 is 17%.”","opts":["percentage","litre","tenth"],"after":"percentage: An amount written as a number out of 100."},"level":5},"word-power":{"id":"word-power","kind":"word","src":"dictionary:power#def","title":"power","body":"A number multiplied by itself a given number of times, like 3⁴. For example: 3⁴ = 3 × 3 × 3 × 3 = 81.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-power":{"id":"wordq-power","kind":"wordq","src":"dictionary:power#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3⁴ = 3 × 3 × 3 × 3 = 81.”","opts":["power","tessellation","Pythagoras’ theorem"],"after":"power: A number multiplied by itself a given number of times, like 3⁴."},"level":5},"word-prime-number":{"id":"word-prime-number","kind":"word","src":"dictionary:prime number#def","title":"prime number","body":"A whole number greater than 1 that only 1 and itself divide exactly. For example: 13: only 1 × 13 makes it.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-prime-number":{"id":"wordq-prime-number","kind":"wordq","src":"dictionary:prime number#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “13: only 1 × 13 makes it.”","opts":["prime number","expression","nth term"],"after":"prime number: A whole number greater than 1 that only 1 and itself divide exactly."},"level":5},"word-product":{"id":"word-product","kind":"word","src":"dictionary:product#def","title":"product","body":"The answer when numbers are multiplied together. For example: For 6 and 7 it is 42.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-product":{"id":"wordq-product","kind":"wordq","src":"dictionary:product#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “For 6 and 7 it is 42.”","opts":["product","polygon","number line"],"after":"product: The answer when numbers are multiplied together."},"level":5},"word-profit":{"id":"word-profit","kind":"word","src":"dictionary:profit#def","title":"profit","body":"The money you make when you sell something for more than it cost you. For example: Buy for £6, sell for £10: £4.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-profit":{"id":"wordq-profit","kind":"wordq","src":"dictionary:profit#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Buy for £6, sell for £10: £4.”","opts":["profit","decimal place","number line"],"after":"profit: The money you make when you sell something for more than it cost you."},"level":5},"word-range":{"id":"word-range","kind":"word","src":"dictionary:range#def","title":"range","body":"The biggest value take away the smallest — how spread out the data is. For example: 4, 9, 12, 20: 20 − 4 = 16.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-range":{"id":"wordq-range","kind":"wordq","src":"dictionary:range#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “4, 9, 12, 20: 20 − 4 = 16.”","opts":["range","compound shape","reflex angle"],"after":"range: The biggest value take away the smallest — how spread out the data is."},"level":5},"word-rectangle":{"id":"word-rectangle","kind":"word","src":"dictionary:rectangle#def","title":"rectangle","body":"A four-sided shape with four right angles, and opposite sides equal. For example: 6 cm by 4 cm: area 24 cm².","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"word-recurring-decimal":{"id":"word-recurring-decimal","kind":"word","src":"dictionary:recurring decimal#def","title":"recurring decimal","body":"A decimal whose digits repeat for ever. For example: 1/3 = 0.333…","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-recurring-decimal":{"id":"wordq-recurring-decimal","kind":"wordq","src":"dictionary:recurring decimal#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “1/3 = 0.333…”","opts":["recurring decimal","million","formula"],"after":"recurring decimal: A decimal whose digits repeat for ever."},"level":5},"word-square-centimetre":{"id":"word-square-centimetre","kind":"word","src":"dictionary:square centimetre#def","title":"square centimetre","body":"The area of a square 1 cm by 1 cm. Written cm². For example: A 3 cm by 2 cm rectangle covers 6 cm².","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-square-centimetre":{"id":"wordq-square-centimetre","kind":"wordq","src":"dictionary:square centimetre#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A 3 cm by 2 cm rectangle covers 6 cm².”","opts":["square centimetre","unit fraction","term"],"after":"square centimetre: The area of a square 1 cm by 1 cm. Written cm²."},"level":5},"word-square-number":{"id":"word-square-number","kind":"word","src":"dictionary:square number#def","title":"square number","body":"What you get when a whole number is multiplied by itself — that many dots make a perfect square. For example: 49 = 7 × 7.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-square-number":{"id":"wordq-square-number","kind":"wordq","src":"dictionary:square number#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “49 = 7 × 7.”","opts":["square number","working backwards","equivalent fractions"],"after":"square number: What you get when a whole number is multiplied by itself — that many dots make a perfect square."},"level":5},"word-squared":{"id":"word-squared","kind":"word","src":"dictionary:squared#def","title":"squared","body":"Multiplied by itself, and written with a small raised 2. For example: 5² = 5 × 5 = 25.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-squared":{"id":"wordq-squared","kind":"wordq","src":"dictionary:squared#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “5² = 5 × 5 = 25.”","opts":["squared","digit root","analogue clock"],"after":"squared: Multiplied by itself, and written with a small raised 2."},"level":5},"word-vertically-opposite-angles":{"id":"word-vertically-opposite-angles","kind":"word","src":"dictionary:vertically opposite angles#def","title":"vertically opposite angles","body":"The equal pair of turns facing each other across the point where two straight lines cross. For example: If one is 40°, the one across is 40° too.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":5},"wordq-vertically-opposite-angles":{"id":"wordq-vertically-opposite-angles","kind":"wordq","src":"dictionary:vertically opposite angles#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “If one is 40°, the one across is 40° too.”","opts":["vertically opposite angles","hundredth","recurring decimal"],"after":"vertically opposite angles: The equal pair of turns facing each other across the point where two straight lines cross."},"level":5},"formula-area-rectangle":{"id":"formula-area-rectangle","kind":"formula","src":"formula:area-rectangle","title":"Area of a rectangle","body":"A = l × w. Each row holds l squares, and there are w rows.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a rectangle: A rectangle 8 cm by 5 cm.","opts":["40","41","39"],"after":"A = 8 × 5 · = 40 cm²"},"level":5},"formula-why-area-rectangle-0":{"id":"formula-why-area-rectangle-0","kind":"formula-why","src":"formula:area-rectangle#why0","title":"Why A = l × w","body":"Cover the rectangle in centimetre squares. Each row along the length holds l squares, and there are w rows the same.","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-why-area-rectangle-1":{"id":"formula-why-area-rectangle-1","kind":"formula-why","src":"formula:area-rectangle#why1","title":"Why A = l × w","body":"Equal rows are exactly what multiplication counts, so the area is l × w square units — no counting one by one. That is why area is measured in cm²: it is a count of squares.","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-story-area-rectangle":{"id":"formula-story-area-rectangle","kind":"formula-story","src":"formula:area-rectangle#story","badge":{"id":"story","label":"A story"},"title":"The kitchen floor","body":"Dax is tiling a kitchen floor. It is 6 tiles long and 4 tiles wide. How many tiles does he need? — with Mira and Dax.","art":"art/s-kitchen.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-try-area-rectangle":{"id":"formula-try-area-rectangle","kind":"formula-try","src":"formula:area-rectangle#gen0","title":"Area of a rectangle — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a rectangle 10 cm by 3 cm (in cm²) = ?","opts":["30","31","29"],"after":"A = l × w"},"level":5},"formula-area-trapezium":{"id":"formula-area-trapezium","kind":"formula","src":"formula:area-trapezium","title":"Area of a trapezium","body":"A = ½ × (a + b) × h. Two trapeziums, one turned over, make a parallelogram with base a + b.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a trapezium: Parallel sides 5 cm and 9 cm, height 4 cm.","opts":["28","29","27"],"after":"a + b = 5 + 9 = 14 · 14 × 4 = 56 · A = 56 ÷ 2 = 28 cm²"},"level":5},"formula-why-area-trapezium-0":{"id":"formula-why-area-trapezium-0","kind":"formula-why","src":"formula:area-trapezium#why0","title":"Why A = ½ × (a + b) × h","body":"Take two copies of the trapezium and turn one upside down. Push them together and they make a parallelogram.","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-why-area-trapezium-1":{"id":"formula-why-area-trapezium-1","kind":"formula-why","src":"formula:area-trapezium#why1","title":"Why A = ½ × (a + b) × h","body":"Its base is a + b — the short side of one next to the long side of the other — and its height is h, so the pair covers (a + b) × h. One trapezium is half of the pair: A = ½ × (a + b) × h.","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-story-area-trapezium":{"id":"formula-story-area-trapezium","kind":"formula-story","src":"formula:area-trapezium#story","badge":{"id":"story","label":"A story"},"title":"The stage ramp","body":"Kwame is painting the side of a stage ramp. It is 2 metres tall at one end, 4 metres at the other, and 5 metres long. — with Kwame and Dax.","art":"art/s-hall.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-try-area-trapezium":{"id":"formula-try-area-trapezium","kind":"formula-try","src":"formula:area-trapezium#gen0","title":"Area of a trapezium — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a trapezium with parallel sides 6 cm and 8 cm, height 9 cm (in cm²) = ?","opts":["63","64","62"],"after":"A = ½ × (a + b) × h"},"level":5},"formula-angles-on-a-line":{"id":"formula-angles-on-a-line","kind":"formula","src":"formula:angles-on-a-line","title":"Angles on a straight line","body":"a + b = 180°. A straight line is a half turn; the pieces share it.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Angles on a straight line: One angle on a straight line is 65°.","opts":["115","116","114"],"after":"180 − 65 = 115°"},"level":5},"formula-why-angles-on-a-line-0":{"id":"formula-why-angles-on-a-line-0","kind":"formula-why","src":"formula:angles-on-a-line#why0","title":"Why a + b = 180°","body":"A straight line is a half turn. Stand facing one way along it, turn to face the other way, and you have turned 180°.","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-why-angles-on-a-line-1":{"id":"formula-why-angles-on-a-line-1","kind":"formula-why","src":"formula:angles-on-a-line#why1","title":"Why a + b = 180°","body":"If another line splits that half turn into two angles, the two pieces still make the whole half turn between them. So angles on a straight line add to 180°, and a missing one is 180° take away the others.","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-story-angles-on-a-line":{"id":"formula-story-angles-on-a-line","kind":"formula-story","src":"formula:angles-on-a-line#story","badge":{"id":"story","label":"A story"},"title":"The leaning book","body":"On the library shelf a book has slipped. It leans at 70° to the shelf. What is the angle on its other side? — with Theo and Nova.","art":"art/s-library.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-try-angles-on-a-line":{"id":"formula-try-angles-on-a-line","kind":"formula-try","src":"formula:angles-on-a-line#gen0","title":"Angles on a straight line — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Two angles sit on a straight line. One is 155°. The other (in °)?","opts":["25","26","24"],"after":"a + b = 180°"},"level":5},"formula-angles-round-a-point":{"id":"formula-angles-round-a-point","kind":"formula","src":"formula:angles-round-a-point","title":"Angles round a point","body":"a + b + c = 360°. However many pieces, together they are one full turn.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Angles round a point: Two of three angles round a point are 100° and 140°.","opts":["120","121","119"],"after":"100 + 140 = 240 · 360 − 240 = 120°"},"level":5},"formula-why-angles-round-a-point-1":{"id":"formula-why-angles-round-a-point-1","kind":"formula-why","src":"formula:angles-round-a-point#why1","title":"Why a + b + c = 360°","body":"Lines coming out of one point cut that full turn into pieces. However many pieces there are, together they are still the one full turn, so they add to 360°.","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-try-angles-round-a-point":{"id":"formula-try-angles-round-a-point","kind":"formula-try","src":"formula:angles-round-a-point#gen0","title":"Angles round a point — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Three angles fill the space round a point. Two are 99° and 181°. The third (in °)?","opts":["80","81","79"],"after":"a + b + c = 360°"},"level":5},"formula-try-percent-of-amount":{"id":"formula-try-percent-of-amount","kind":"formula-try","src":"formula:percent-of-amount#gen0","title":"A percentage of an amount — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"40% of 280 = ?","opts":["112","113","111"],"after":"p% of x = x ÷ 100 × p"},"level":5},"formula-mean":{"id":"formula-mean","kind":"formula","src":"formula:mean","title":"The mean","body":"mean = total ÷ how many. Tall bars give to short ones until every bar is level.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"The mean: The mean of 4, 7 and 10.","opts":["7","8","6"],"after":"4 + 7 + 10 = 21 · 21 ÷ 3 = 7"},"level":5},"formula-why-mean-0":{"id":"formula-why-mean-0","kind":"formula-why","src":"formula:mean#why0","title":"Why mean = total ÷ how many","body":"The mean asks: if everything were shared out fairly, how much would each get? Put all the values together into one pile — that is the total.","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-why-mean-1":{"id":"formula-why-mean-1","kind":"formula-why","src":"formula:mean#why1","title":"Why mean = total ÷ how many","body":"Then share the pile equally between all of them: total ÷ how many. Tall bars give some to short bars until every bar is the same height; that height is the mean.","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-story-mean":{"id":"formula-story-mean","kind":"formula-story","src":"formula:mean#story","badge":{"id":"story","label":"A story"},"title":"Sharing the sweets","body":"At the festival Nova collects 9 sweets, Suki 4 and their friend 8. They agree to share them out fairly. — with Nova and Suki.","art":"art/s-festival.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-try-mean":{"id":"formula-try-mean","kind":"formula-try","src":"formula:mean#gen0","title":"The mean — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"The mean of 12, 8, 7?","opts":["9","10","8"],"after":"mean = total ÷ how many"},"level":5},"formula-range":{"id":"formula-range","kind":"formula","src":"formula:range","title":"The range","body":"range = biggest − smallest. Only the two ends matter.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"The range: The range of 12, 5, 19 and 8.","opts":["14","15","13"],"after":"biggest 19, smallest 5 · 19 − 5 = 14"},"level":5},"formula-why-range-0":{"id":"formula-why-range-0","kind":"formula-why","src":"formula:range#why0","title":"Why range = biggest − smallest","body":"The range tells you how spread out the data is: the distance from the smallest value to the biggest.","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-why-range-1":{"id":"formula-why-range-1","kind":"formula-why","src":"formula:range#why1","title":"Why range = biggest − smallest","body":"Only the two ends matter, so hunt for the biggest and the smallest and take one from the other. A big range means the values are spread wide; a small one means they bunch together.","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-story-range":{"id":"formula-story-range","kind":"formula-story","src":"formula:range#story","badge":{"id":"story","label":"A story"},"title":"The long jump","body":"Dax’s long jumps at sports day: 310 cm, 285 cm, 342 cm and 298 cm. How spread out are they? — with Dax and Suki.","art":"art/s-stadium.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":5},"formula-try-range":{"id":"formula-try-range","kind":"formula-try","src":"formula:range#gen0","title":"The range — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"The range of 23, 48, 32, 51, 55, 17, 54?","opts":["38","39","37"],"after":"range = biggest − smallest"},"level":5},"stone-vedic-origin":{"src":"journey:vedic/origin#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965). S. G. Dani, \"Myths and reality: on 'Vedic mathematics'\", Frontline, 1993.","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-origin","kind":"stone","title":"Where the sutras come from","body":"The short Sanskrit sayings in this part of the Atlas — the sutras — were set out by Bharati Krishna Tirtha in a book called Vedic Mathematics, published in 1965, five years after he died.","level":5},"stone-vedic-origin-1":{"src":"journey:vedic/origin#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965). S. G. Dani, \"Myths and reality: on 'Vedic mathematics'\", Frontline, 1993.","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-origin-1","kind":"stone-step","title":"Where the sutras come from (2 of 4)","body":"He said they came from the Vedas. Scholars who have looked have not found them in any Vedic text, so the honest name is: methods from a twentieth-century Indian book, with Sanskrit names.","level":5},"stone-vedic-origin-2":{"src":"journey:vedic/origin#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965). S. G. Dani, \"Myths and reality: on 'Vedic mathematics'\", Frontline, 1993.","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-origin-2","kind":"stone-step","title":"Where the sutras come from (3 of 4)","body":"That takes nothing away from them. They are quick, they are clever, and every one of them works for a reason you can check — ordinary algebra. That reason is what each stop here shows you.","level":5},"stone-vedic-origin-3":{"src":"journey:vedic/origin#3","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965). S. G. Dani, \"Myths and reality: on 'Vedic mathematics'\", Frontline, 1993.","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-origin-3","kind":"stone-step","title":"Where the sutras come from (4 of 4)","body":"The book gives sixteen short sutras, and some shorter sub-sutras that go with them. This path walks through the ones you can use with a pencil — or with no pencil at all. On every stone you will see the method, then the algebra that makes it work, then try it yourself.","level":5},"stone-vedic-ekadhika":{"src":"journey:vedic/ekadhika#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-ekadhika","kind":"stone","title":"One more than the one before — Ekādhikena Pūrvena","body":"To square a number that ends in 5, look at the digits in front of the 5. Multiply them by one more than themselves. Then write 25 on the end.","level":5},"stone-vedic-ekadhika-1":{"src":"journey:vedic/ekadhika#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-ekadhika-1","kind":"stone-step","title":"One more than the one before (2 of 4)","body":"65²: in front of the 5 is 6. One more than 6 is 7, and 6 × 7 = 42. Write 25 after it: 4225.","level":5},"stone-vedic-ekadhika-2":{"src":"journey:vedic/ekadhika#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-ekadhika-2","kind":"stone-step","title":"One more than the one before (3 of 4)","body":"Why it works: a number ending in 5 is 10n + 5. Squared, that is 100n² + 100n + 25, which is 100 × n(n + 1) + 25. The n(n + 1) is the \"one more than the one before\"; the 25 is 5 × 5.","level":5},"stone-vedic-ekadhika-3":{"src":"journey:vedic/ekadhika#3","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-ekadhika-3","kind":"stone-step","title":"One more than the one before (4 of 4)","body":"The same sutra makes the digits of 1 ÷ 19. The digit before the 9 in 19 is 1, and one more than it is 2 — so start from the right with 1, and keep doubling to the left, carrying as you go. You get all eighteen digits that repeat: 0.052631578947368421… (on the Stretch level you try this too).","level":5},"stone-try-vedic-ekadhika":{"src":"journey:vedic/ekadhika#gen0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-try-vedic-ekadhika","kind":"stone-try","title":"One more than the one before — try it","play":{"q":"95² = ?","opts":["9025","90","9026"],"after":"Squares ending in 5"},"level":5},"stone-vedic-antyayor":{"src":"journey:vedic/antyayor#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-antyayor","kind":"stone","title":"When the last digits make ten — Antyayordaśake'pi","body":"This is a sub-sutra that goes with \"one more than the one before\". It works when the front parts are the same and the last digits add up to 10 — like 43 × 47 (3 + 7 = 10).","level":5},"stone-vedic-antyayor-1":{"src":"journey:vedic/antyayor#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-antyayor-1","kind":"stone-step","title":"When the last digits make ten (2 of 3)","body":"Multiply the front by one more than itself: 4 × 5 = 20. Multiply the last digits: 3 × 7 = 21. Side by side: 2021. If the last digits multiply to one digit, write a 0 first: 51 × 59 → 30 and 09 → 3009.","level":5},"stone-vedic-antyayor-2":{"src":"journey:vedic/antyayor#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-vedic-antyayor-2","kind":"stone-step","title":"When the last digits make ten (3 of 3)","body":"Why: (10n + b)(10n + 10 − b) = 100 × n(n + 1) + b(10 − b). Squares ending in 5 are the special case where both last digits are 5.","level":5},"stone-try-vedic-antyayor":{"src":"journey:vedic/antyayor#gen0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic","cta":"Walk the Vedic Maths Journey","id":"stone-try-vedic-antyayor","kind":"stone-try","title":"When the last digits make ten — try it","play":{"q":"64 × 66 = ?","opts":["4224","42","24"],"after":"43 × 47 in one breath"},"level":5}};
